(window.BUNKAZAI_DETAIL=window.BUNKAZAI_DETAIL||{})["c23"]=[{"id":"00003530","register_sub_id":"101","register_pk":"104520","name":"今半別館北棟","kana":"いまはんべっかんきたとう","category":"産業3次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和中","pref":"東京都","address":"東京都台東区浅草2-2-5","lat":35.71315638,"lng":139.79691848,"geo_status":"db","era":"昭和25頃","year":1950,"year_source":"db","year_min":1950,"year_max":1950,"year_label":null,"structure":"木造2階建、瓦葺、建築面積173㎡","structure_material":"木造2階建","registered":"2003.09.19(平成15.09.19)","register_no":"13 － 0161","desc":"玄関棟の北東，中庭を挟んで南棟と対面して建つ。２階建，正面入母屋造，東面切妻造，桟瓦葺で，１階に厨房，配膳室，事務室，２階に大小の座敷を配する。大広間の大床と飾棚による豪華な構成，次の間天井の鳳凰彫物など，宴会場の晴れやかな空間を演出する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003530"},{"id":"00003528","register_sub_id":"101","register_pk":"104518","name":"今半別館玄関棟","kana":"いまはんべっかんげんかんとう","category":"産業3次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和中","pref":"東京都","address":"東京都台東区浅草2-2-5","lat":35.71311121,"lng":139.79683051,"geo_status":"db","era":"昭和25頃","year":1950,"year_source":"db","year_min":1950,"year_max":1950,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積66㎡","structure_material":"木造平屋建","registered":"2003.09.19(平成15.09.19)","register_no":"13 － 0159","desc":"今半別館は，今半本店の三田支店が戦後，現在地に移り別館として創業。入母屋造，桟瓦葺の玄関棟は，仲見世通り東裏手の通りから奥まって建ち，入口脇に座敷２室を配す。狭い敷地を巧みに利用し，老舗料理屋に相応しい構えを造る。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003528"},{"id":"00003529","register_sub_id":"101","register_pk":"104519","name":"今半別館南棟","kana":"いまはんべっかんみなみとう","category":"産業3次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和中","pref":"東京都","address":"東京都台東区浅草2-2-5","lat":35.71305569,"lng":139.79690513,"geo_status":"db","era":"昭和25頃","year":1950,"year_source":"db","year_min":1950,"year_max":1950,"year_label":null,"structure":"木造2階建、瓦葺、建築面積75㎡","structure_material":"木造2階建","registered":"2003.09.19(平成15.09.19)","register_no":"13 － 0160","desc":"玄関棟の南東に接続する。２階建，切妻造，桟瓦葺で，敷地の関係からＬ字型の平面とする。１，２階とも片廊下に沿い客室を配し，１階東端には旧風呂場も残る。室内は各室とも座敷飾りを備え，天井，建具，欄間とも，銘木をふんだんに使い職人芸の粋を凝らす。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003529"},{"id":"00014458","register_sub_id":"101","register_pk":"512442","name":"今半本店北奥座敷","kana":"いまはんほんてんきたおくざしき","category":"産業3次","subcategory":"建築物","type_guess":"店舗","type_guess_confidence":"high","period":"昭和中","pref":"東京都","address":"東京都台東区浅草一丁目2-5","lat":35.71160833,"lng":139.79686944,"geo_status":"db","era":"昭和31年頃／平成17年・同26年改修","year":1956,"year_source":"db","year_min":1956,"year_max":1956,"year_label":null,"structure":"木造平屋建、鉄板葺、建築面積35㎡","structure_material":"木造平屋建","registered":"2023.02.27(令和5.02.27)","register_no":"13 - 0474","desc":"仲見世通り東の街区中心に位置する料亭座敷棟。切妻造で元瓦葺。南側片廊下で四畳半大の座敷を三室並べる。東西両奥座敷の銘木趣味や用材に凝る造りと異なり、組子建具や網代天井等技法に凝る造り。すき焼き料亭に典型的な小座敷で構成する数寄屋風の座敷棟。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014458"},{"id":"00014456","register_sub_id":"101","register_pk":"512440","name":"今半本店西奥座敷","kana":"いまはんほんてんにしおくざしき","category":"産業3次","subcategory":"建築物","type_guess":"店舗","type_guess_confidence":"high","period":"昭和中","pref":"東京都","address":"東京都台東区浅草一丁目2-5","lat":35.71156667,"lng":139.79676111,"geo_status":"db","era":"昭和26年頃／平成26年改修","year":1951,"year_source":"db","year_min":1951,"year_max":1951,"year_label":null,"structure":"木造平屋建、鉄板葺、建築面積36㎡","structure_material":"木造平屋建","registered":"2023.02.27(令和5.02.27)","register_no":"13 - 0472","desc":"仲見世通り東の街区中央にある料亭座敷棟。切妻造で元瓦葺。高床式で床下を収蔵庫とする。北側片廊下で床付き四畳半を三室並べ、春日・吉野・神代の部屋名とし、天井板等にそれぞれの杉材を用いる。すき焼き料亭に典型的な小座敷で構成する数寄屋風の座敷棟。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014456"},{"id":"00014457","register_sub_id":"101","register_pk":"512441","name":"今半本店東奥座敷","kana":"いまはんほんてんひがしおくざしき","category":"産業3次","subcategory":"建築物","type_guess":"店舗","type_guess_confidence":"high","period":"昭和中","pref":"東京都","address":"東京都台東区浅草一丁目2-5","lat":35.71156111,"lng":139.79686389,"geo_status":"db","era":"昭和26年頃／平成26年改修","year":1951,"year_source":"db","year_min":1951,"year_max":1951,"year_label":null,"structure":"木造平屋建、鉄板葺、建築面積53㎡","structure_material":"木造平屋建","registered":"2023.02.27(令和5.02.27)","register_no":"13 - 0473","desc":"仲見世通り東街区内に位置する数寄屋風の座敷棟。切妻造で元瓦葺。北側に玄関付片廊下を配し六畳を三室並べ、松・竹・梅の部屋名とし、床柱や天井棹縁等にそれぞれの材を用いる。竹の間は床を構えず松と梅の続き間とし、すき焼き料亭の小座敷と大宴会に対応。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014457"},{"id":"00014455","register_sub_id":"101","register_pk":"512439","name":"エチソウビル","kana":"えちそうびる","category":"産業3次","subcategory":"建築物","type_guess":"店舗","type_guess_confidence":"high","period":"大正","pref":"東京都","address":"東京都文京区本郷二丁目306-1","lat":35.70647778,"lng":139.76050556,"geo_status":"db","era":"大正後期／昭和7年頃・同61年・平成14年改修","year":1922,"year_source":"estimated","year_min":1919,"year_max":1926,"year_label":"大正後期","structure":"鉄筋コンクリート造3階建、建築面積236㎡","structure_material":"鉄筋コンクリート造3階建","registered":"2023.02.27(令和5.02.27)","register_no":"13 - 0471","desc":"エチソウビルは本郷通沿い角地に建つ糸物商、越惣商店の自社ビル。西側既存部を取り込み昭和初期に増築した鉄筋コンクリート造三階建塔屋付で南東隅を一段高くする。頂部のデンティルや窓上のアーチ等で飾る外観はアイストップとして街区の景観を形成する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014455"},{"id":"00009907","register_sub_id":"101","register_pk":"196054","name":"江戸屋店舗兼住宅","kana":"えどやてんぽけんじゅうたく","category":"産業3次","subcategory":"建築物","type_guess":"店舗","type_guess_confidence":"high","period":"大正","pref":"東京都","address":"東京都中央区日本橋大伝馬町1-5","lat":35.68933492,"lng":139.77807345,"geo_status":"db","era":"大正13","year":1924,"year_source":"db","year_min":1924,"year_max":1924,"year_label":null,"structure":"木造2階建、鋼板葺、建築面積94㎡","structure_material":"木造2階建","registered":"2014.04.25(平成26.04.25)","register_no":"13 － 0322","desc":"通りに面して建つ、木造二階建、人造石洗出し仕上げのいわゆる看板建築で、正面意匠は刷毛を表す。間口六・二メートル奥行一九・六メートルで、一階は店舗、事務所、倉庫、二階は居室及び倉庫とする。内外共に改修も少なく、建具や金庫も当初のものを残す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009907"},{"id":"00011272","register_sub_id":"101","register_pk":"209108","name":"青梅織物工業協同組合旧都立繊維試験場","kana":"おうめおりものこうぎょうきょうどうくみあいきゅうとりつせんいしけんじょう","category":"産業3次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"東京都","address":"東京都青梅市西分町三丁目123","lat":35.78822,"lng":139.266002,"geo_status":"db","era":"昭和10頃／昭和22頃移築、平成9・同18改修","year":1935,"year_source":"db","year_min":1935,"year_max":1935,"year_label":null,"structure":"木造平屋建、スレート葺、建築面積236㎡","structure_material":"木造平屋建","registered":"2016.11.29(平成28.11.29)","register_no":"13－0370","desc":"木造平屋建、寄棟造スレート葺の洋館。当初は府立染織試験場出張所として建てられたと推測される。外壁は下見板張とし、全体を簡素な意匠でまとめる。正面玄関アーチ上部には小ぶりなペディメントを立ち上げアクセントとする。青梅の繁栄を今に伝える洋館。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011272"},{"id":"00011271","register_sub_id":"101","register_pk":"209107","name":"青梅織物工業協同組合本館","kana":"おうめおりものこうぎょうきょうどうくみあいほんかん","category":"産業3次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"東京都","address":"東京都青梅市西分町三丁目123他","lat":35.788573,"lng":139.266076,"geo_status":"db","era":"昭和15頃／昭和38増築","year":1940,"year_source":"db","year_min":1940,"year_max":1940,"year_label":null,"structure":"木造2階建、スレート葺、建築面積280㎡","structure_material":"木造2階建","registered":"2016.11.29(平成28.11.29)","register_no":"13－0369","desc":"青梅市街地の中ほどに立地する。屋根を寄棟造スレート葺とする木造二階建で、南面に玄関ポーチを設け、東面北寄りに増築された応接室が突出する。一階は事務室等、二階は増築部を除いて一室の大空間とする。織物で栄えた青梅の歴史を今に伝える建物。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011271"},{"id":"00009908","register_sub_id":"101","register_pk":"196055","name":"大野屋總本店店舗","kana":"おおのやそうほんてんてんぽ","category":"産業3次","subcategory":"建築物","type_guess":"店舗","type_guess_confidence":"high","period":"大正","pref":"東京都","address":"東京都中央区新富2-6-13","lat":35.67215508,"lng":139.77267322,"geo_status":"db","era":"大正13頃／昭和30頃改修","year":1924,"year_source":"db","year_min":1924,"year_max":1924,"year_label":null,"structure":"木造2階建、瓦葺、建築面積27㎡","structure_material":"木造2階建","registered":"2014.04.25(平成26.04.25)","register_no":"13 － 0323","desc":"角地に北面して建つ。木造二階建、切妻造桟瓦葺で、重厚な甍棟を積む。一階は店舗とし、二階で足袋製造を行う。上下階とも軒が高く、二階は出桁造とする。外壁は簓子下見板張で二階窓に手摺を設ける。震災直後に建てられた、当地に残る数少ない戦前の町家建築。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009908"},{"id":"00005591","register_sub_id":"101","register_pk":"106579","name":"大橋茶寮表門","kana":"おおはしさりょうおもてもん","category":"産業3次","subcategory":"その他工作物","type_guess":"塀・門","type_guess_confidence":"high","period":"昭和中","pref":"東京都","address":"東京都港区虎ノ門5-6-6","lat":35.66286608,"lng":139.74236998,"geo_status":"db","era":"昭和24頃","year":1949,"year_source":"db","year_min":1949,"year_max":1949,"year_label":null,"structure":"木造、瓦葺、間口2.7m","structure_material":"木造","registered":"2006.08.03(平成18.08.03)","register_no":"13 － 0205","desc":"敷地東辺の中央やや北寄りに位置し，幅２．７ｍの棟門形式で，木造，切妻造，桟瓦葺とする。扉は両開きの板戸で，壁面を土壁とし，下部を横板張とする。桁や垂木などに丸太材を用い，数寄屋風とする。茶寮の質素で落ち着きのある景観を形成している。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005591"},{"id":"00005587","register_sub_id":"101","register_pk":"106575","name":"大橋茶寮茶室葵","kana":"おおはしさりょうちゃしつあおい","category":"産業3次","subcategory":"建築物","type_guess":"橋","type_guess_confidence":"low","period":"昭和中","pref":"東京都","address":"東京都港区虎ノ門5-6-6","lat":35.66289537,"lng":139.74216375,"geo_status":"db","era":"昭和24頃","year":1949,"year_source":"db","year_min":1949,"year_max":1949,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積101㎡","structure_material":"木造平屋建","registered":"2006.08.03(平成18.08.03)","register_no":"13 － 0201","desc":"敷地北西の隅に建ち，敷地中央の庭を座敷から望む配置とする。木造平屋建，切妻造，桟瓦葺とする。座敷を８畳間と６畳間の続き間とし，座敷西側に水屋を設け，その周りに廊下を廻し，北側を調理場とする。床構え等，京都裏千家の茶室咄々斎を模倣する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005587"},{"id":"00005586","register_sub_id":"101","register_pk":"106574","name":"大橋茶寮茶室桂","kana":"おおはしさりょうちゃしつかつら","category":"産業3次","subcategory":"建築物","type_guess":"橋","type_guess_confidence":"low","period":"昭和中","pref":"東京都","address":"東京都港区虎ノ門5-6-6","lat":35.66279092,"lng":139.742157,"geo_status":"db","era":"昭和24頃","year":1949,"year_source":"db","year_min":1949,"year_max":1949,"year_label":null,"structure":"木造平屋建、瓦葺一部銅板葺、建築面積49㎡","structure_material":"木造平屋建","registered":"2006.08.03(平成18.08.03)","register_no":"13 － 0200","desc":"敷地南西隅に位置し，床構えなど桂離宮の意匠を模倣して建築する。桁行４間，梁間３間半の規模で，木造平屋建，切妻造，桟瓦葺とする。１２畳間の座敷を設け，北側と東側を入側とする。東面北端に庭への階段を設け，庭と一体となった空間構成とする。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005586"},{"id":"00005590","register_sub_id":"101","register_pk":"106578","name":"大橋茶寮茶室守貧庵","kana":"おおはしさりょうちゃしつしゅひんあん","category":"産業3次","subcategory":"建築物","type_guess":"橋","type_guess_confidence":"low","period":"昭和中","pref":"東京都","address":"東京都港区虎ノ門5-6-6","lat":35.66275648,"lng":139.74230598,"geo_status":"db","era":"昭和24頃","year":1949,"year_source":"db","year_min":1949,"year_max":1949,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積19㎡","structure_material":"木造平屋建","registered":"2006.08.03(平成18.08.03)","register_no":"13 － 0204","desc":"敷地南辺に接し，中央やや東側に建つ。木造平屋建，入母屋造，桟瓦葺とし，外壁を土壁として腰を杉皮張とする。６畳の座敷に床及び隠し仏壇を付属する。南側に廊下を設け，その東端を雪隠とし，さらに東側に腰掛待合を突出させる。質の高い茶室を構成している。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005590"},{"id":"00005589","register_sub_id":"101","register_pk":"106577","name":"大橋茶寮茶室如庵写","kana":"おおはしさりょうちゃしつじょあんうつし","category":"産業3次","subcategory":"建築物","type_guess":"橋","type_guess_confidence":"low","period":"昭和中","pref":"東京都","address":"東京都港区虎ノ門5-6-6","lat":35.66281342,"lng":139.74234996,"geo_status":"db","era":"昭和24頃","year":1949,"year_source":"db","year_min":1949,"year_max":1949,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積14㎡","structure_material":"木造平屋建","registered":"2006.08.03(平成18.08.03)","register_no":"13 － 0203","desc":"敷地東辺のやや南側に位置し，木造平屋建，切妻造，桟瓦葺とし，柱に丸太材を使い，外壁を土壁とする。西側にこけら葺の庇を架ける。北側に水屋を設け，その北側を茶室山吹と接続する。３畳半敷きの小規模な建物で，国宝の如庵を模倣してつくる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005589"},{"id":"00005588","register_sub_id":"101","register_pk":"106576","name":"大橋茶寮茶室山吹","kana":"おおはしさりょうちゃしつやまぶき","category":"産業3次","subcategory":"建築物","type_guess":"橋","type_guess_confidence":"low","period":"昭和中","pref":"東京都","address":"東京都港区虎ノ門5-6-6","lat":35.66289949,"lng":139.74230926,"geo_status":"db","era":"昭和24頃","year":1949,"year_source":"db","year_min":1949,"year_max":1949,"year_label":null,"structure":"木造平屋建、瓦葺一部銅板葺、建築面積96㎡","structure_material":"木造平屋建","registered":"2006.08.03(平成18.08.03)","register_no":"13 － 0202","desc":"敷地東辺の中央に位置し，木造平屋建，切妻造，桟瓦葺で，外壁を土壁とする。８畳間の座敷を庭に面し，その東側を水屋とする。座敷の北側に茶寮の玄関を設ける。玄関の北側に控室等を設け敷地北東隅を構成する。高度な数寄屋の技術を用いた茶室を構成する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005588"},{"id":"00005593","register_sub_id":"101","register_pk":"106581","name":"大橋茶寮中門","kana":"おおはしさりょうちゅうもん","category":"産業3次","subcategory":"その他工作物","type_guess":"塀・門","type_guess_confidence":"high","period":"昭和中","pref":"東京都","address":"東京都港区虎ノ門5-6-6","lat":35.66282793,"lng":139.74226849,"geo_status":"db","era":"昭和24頃","year":1949,"year_source":"db","year_min":1949,"year_max":1949,"year_label":null,"structure":"木造、杉皮葺、間口1.0m","structure_material":"木造","registered":"2006.08.03(平成18.08.03)","register_no":"13 － 0207","desc":"敷地中央の庭に設けられた，間口１ｍの棟門形式の門である。屋根は切妻造，杉皮葺とし，竹を屋根葺材の押さえに使う。柱や桁に細い丸太を使い，柱は添え木をして立てる。各茶室を行き来する門として，数寄屋風の落ち着いた意匠を見せ，各茶室を結びつけている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005593"},{"id":"00005592","register_sub_id":"101","register_pk":"106580","name":"大橋茶寮不老門","kana":"おおはしさりょうふろうもん","category":"産業3次","subcategory":"その他工作物","type_guess":"塀・門","type_guess_confidence":"high","period":"昭和中","pref":"東京都","address":"東京都港区虎ノ門5-6-6","lat":35.66275504,"lng":139.74222566,"geo_status":"db","era":"昭和24頃","year":1949,"year_source":"db","year_min":1949,"year_max":1949,"year_label":null,"structure":"木造、銅板葺、間口1.5m","structure_material":"木造","registered":"2006.08.03(平成18.08.03)","register_no":"13 － 0206","desc":"敷地南辺の中央やや西寄りに位置し，敷地境より少し奥まって建つ。間口１．５ｍの木造の棟門の形式で，切妻造，銅板葺の屋根を載せる。板戸２枚を内開きとし，正面に菱目に組んだ桟を付け，意匠とする。柱や桁に丸太材を用い，数寄屋風の落ち着いた意匠とする。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005592"},{"id":"00005594","register_sub_id":"101","register_pk":"106582","name":"大橋茶寮塀","kana":"おおはしさりょうへい","category":"産業3次","subcategory":"その他工作物","type_guess":"塀・門","type_guess_confidence":"high","period":"昭和中","pref":"東京都","address":"東京都港区虎ノ門5-6-6","lat":35.66275004,"lng":139.74238095,"geo_status":"db","era":"昭和24頃","year":1949,"year_source":"db","year_min":1949,"year_max":1949,"year_label":null,"structure":"木造、延長53m","structure_material":"木造","registered":"2006.08.03(平成18.08.03)","register_no":"13 － 0208","desc":"敷地南辺，東辺，北辺の東半を囲う塀で，木造，モルタル塗とする。 建物が接する部分では建物外壁を兼ねる。大谷石の基礎の上に丸太柱を立て，正面東辺は柱を見せ，下部を横板張とし，南端間に潜戸を設ける。南面，北面は柱を塗り込め，上部に笠木を置く。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005594"},{"id":"00013369","register_sub_id":"101","register_pk":"368456","name":"河鹿園稲荷社","kana":"かじかえんいなりしゃ","category":"産業3次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和中","pref":"東京都","address":"東京都青梅市御岳本町335","lat":35.80101667,"lng":139.18418611,"geo_status":"db","era":"昭和30年頃","year":1955,"year_source":"db","year_min":1955,"year_max":1955,"year_label":null,"structure":"木造、銅板葺、面積0.36㎡","structure_material":"木造","registered":"2020.08.17(令和2.08.17)","register_no":"13 － 0447","desc":"枕流亭北の中庭に建つ一間社流造で、北西を正面とする。石積み基壇上に布基礎を廻し、土台建とする。正面に浜床、浜縁を付し、浜床上に庇柱を立て、木階五級を備える。水引虹梁上に蟇股を据え、妻飾りは虹梁大瓶束笈形付。小社ながら本格的な造りである。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013369"},{"id":"00013364","register_sub_id":"101","register_pk":"368451","name":"河鹿園渓梅庵","kana":"かじかえんけいばいあん","category":"産業3次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"東京都","address":"東京都青梅市御岳本町335","lat":35.80096667,"lng":139.18406667,"geo_status":"db","era":"昭和5年頃／昭和39年頃改修、平成元年増築","year":1930,"year_source":"db","year_min":1930,"year_max":1930,"year_label":null,"structure":"木造2階建、銅板葺、建築面積104㎡","structure_material":"木造2階建","registered":"2020.08.17(令和2.08.17)","register_no":"13 － 0442","desc":"山魚楼の東、一段下に並ぶ東西棟である。北側渡廊下の高低差を利用して一、二階に別の入口を設ける。一階は藤の間六畳、桔梗の間八畳、つばきの間八畳が並ぶ。二階百合の間は八畳と六畳の続き間である。床柱や落掛けの磨き丸太が目を引く数寄屋座敷である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013364"},{"id":"00013363","register_sub_id":"101","register_pk":"368450","name":"河鹿園山魚楼","kana":"かじかえんさんぎょろう","category":"産業3次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"東京都","address":"東京都青梅市御岳本町335","lat":35.80098333,"lng":139.18390556,"geo_status":"db","era":"昭和5年頃","year":1930,"year_source":"db","year_min":1930,"year_max":1930,"year_label":null,"structure":"木造2階建、銅板葺、建築面積72㎡","structure_material":"木造2階建","registered":"2020.08.17(令和2.08.17)","register_no":"13 － 0441","desc":"川に面して建つ寄棟造の東西棟。北面に庇付の吹放ち玄関を備え、東に外向きで半間の床を設ける。一階月の間は八畳二室、二階もみじの間は一〇畳二室の続き間で、南側縁には桟割の大きなガラス障子を建込む。銘木を用い、落ち着いた造作の数寄屋座敷である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013363"},{"id":"00013366","register_sub_id":"101","register_pk":"368453","name":"河鹿園射山荘","kana":"かじかえんしゃざんそう","category":"産業3次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"東京都","address":"東京都青梅市御岳本町335","lat":35.80113611,"lng":139.18400278,"geo_status":"db","era":"昭和5年／平成元年増築","year":1930,"year_source":"db","year_min":1930,"year_max":1930,"year_label":null,"structure":"木造2階建、金属板葺、建築面積203㎡","structure_material":"木造2階建","registered":"2020.08.17(令和2.08.17)","register_no":"13 － 0444","desc":"敷地中央の北寄りに建つ入母屋造の東西棟である。南面西端に玄関を構え、一階は五一畳の大広間とする。二階は松の間八畳ほかの宿泊室で、各室に洋箪笥を造付ける。床回りに変り木などの銘木を多用し、上面を凸に造った違棚など、独創的な造作を用いる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013366"},{"id":"00013367","register_sub_id":"101","register_pk":"368454","name":"河鹿園大浴場","kana":"かじかえんだいよくじょう","category":"産業3次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"東京都","address":"東京都青梅市御岳本町335","lat":35.80108611,"lng":139.18421667,"geo_status":"db","era":"昭和前期／平成元年増築","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和前期","structure":"木造平屋建、銅板葺、建築面積94㎡","structure_material":"木造平屋建","registered":"2020.08.17(令和2.08.17)","register_no":"13 － 0445","desc":"射山荘の東下方に建つ切妻造の南北棟で、西面に渡廊下が取り付く。南東の大浴場はタイル貼の円形浴槽をもち、南面から東面に大きなガラス窓を建て開放的に造る。北東に川原石を組上げた岩風呂、南西には木製浴槽の小浴室を設ける。多様な趣を備えた浴場。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013367"},{"id":"00013362","register_sub_id":"101","register_pk":"368449","name":"河鹿園帳場兼主屋","kana":"かじかえんちょうばけんおもや","category":"産業3次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"大正","pref":"東京都","address":"東京都青梅市御岳本町335","lat":35.80112222,"lng":139.18378889,"geo_status":"db","era":"大正14年頃／昭和50年増築","year":1925,"year_source":"db","year_min":1925,"year_max":1925,"year_label":null,"structure":"木造2階建、金属板葺、建築面積152㎡","structure_material":"木造2階建","registered":"2020.08.17(令和2.08.17)","register_no":"13 － 0440","desc":"ＪＲ青梅線御嶽駅の近傍、多摩川左岸の崖上にある敷地の北西の入口に建つ。東西棟で、南正面中央の土間沿いに帳場を設け、北面に厨房を配す。一階西半と二階は住居及び従業員休憩室とする。観光地の休憩所として使用した開業当初に遡る建物である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013362"},{"id":"00013365","register_sub_id":"101","register_pk":"368452","name":"河鹿園枕流亭","kana":"かじかえんちんりゅうてい","category":"産業3次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"東京都","address":"東京都青梅市御岳本町335","lat":35.80093889,"lng":139.18422778,"geo_status":"db","era":"昭和5年頃／昭和29年移築・増築","year":1930,"year_source":"db","year_min":1930,"year_max":1930,"year_label":null,"structure":"木造2階建、銅板葺、建築面積55㎡","structure_material":"木造2階建","registered":"2020.08.17(令和2.08.17)","register_no":"13 － 0443","desc":"渓梅庵の東下方に建つ入母屋造の東西棟である。敷地内で最も低い位置で、渡廊下は二階に取付く。一階は八畳二室、二階のやまぶきの間は八畳二室の続き間で、縁は設けず川に向かって開放的な室とする。上質な客室棟で、奥多摩観光の隆盛を伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013365"},{"id":"00013368","register_sub_id":"101","register_pk":"368455","name":"河鹿園渡廊下","kana":"かじかえんわたりろうか","category":"産業3次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"東京都","address":"東京都青梅市御岳本町335","lat":35.80103889,"lng":139.18414722,"geo_status":"db","era":"昭和前期／昭和29年増築、平成元年改修","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和前期","structure":"木造平屋建、金属板葺、建築面積62㎡","structure_material":"木造平屋建","registered":"2020.08.17(令和2.08.17)","register_no":"13 － 0446","desc":"山魚楼北から渓梅庵北を通り、枕流亭と大浴場へ到る渡廊下。南東下がりの敷地を、階段二箇所と斜路で結ぶ。床面は黒色玉石のモルタル洗出しで、飛石状の切株を擬木で造る。腰壁は竪板張で引違窓を設ける。地形に合わせて曲折しながら巧みにまとめる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013368"},{"id":"00008827","register_sub_id":"101","register_pk":"162270","name":"割烹美家古向島本店店舗","kana":"かっぽうみやこむこうじまほんてんてんぽ","category":"産業3次","subcategory":"建築物","type_guess":"料亭","type_guess_confidence":"high","period":"昭和前","pref":"東京都","address":"東京都墨田区向島5-2-1","lat":35.71715217,"lng":139.80876753,"geo_status":"db","era":"昭和前期／昭和中期・平成9年改修","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和前期","structure":"木造2階建、瓦葺一部鉄板葺、建築面積224㎡","structure_material":"木造2階建","registered":"2011.10.28(平成23.10.28)","register_no":"13 － 0286","desc":"通り西側に占める短冊形敷地の東寄りに位置する。中庭を5棟が囲む木造2階建で、建築面積224㎡。中庭側に廊下をめぐらし、客室などを周囲に配する。良材を多用し、各室で天井仕様などを違える。近代向島の雰囲気を伝える料亭建築。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008827"},{"id":"00008826","register_sub_id":"101","register_pk":"162269","name":"神谷バー本館","kana":"かみやばーほんかん","category":"産業3次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"大正","pref":"東京都","address":"東京都台東区浅草1-16-33他","lat":35.71094424,"lng":139.7975212,"geo_status":"db","era":"大正10年","year":1921,"year_source":"db","year_min":1921,"year_max":1921,"year_label":null,"structure":"鉄筋コンクリート造6階地下1階建、建築面積181㎡","structure_material":"鉄筋コンクリート造6階地下1階建","registered":"2011.10.28(平成23.10.28)","register_no":"13 － 0285","desc":"西北角地に南面して建つ。鉄筋コンクリート造6階地下1階建、建築面積181㎡。正面には矩形の大きな窓と円形の高窓を穿ち、隅には付柱を飾る。3・4階を通す、三連の半円アーチ窓が外観を特徴付ける。正面性を重視した近代商業建築。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008826"},{"id":"00000959","register_sub_id":"101","register_pk":"101949","name":"ギャラリー・エフ蔵（株式会社淵川金属事務所）","kana":"ぎゃらりー・えふぐら（かぶしきがいしゃふちかわきんぞくじむしょ）","category":"産業3次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"high","period":"江戸","pref":"東京都","address":"東京都台東区雷門二丁目6-1","lat":35.70990739,"lng":139.79688411,"geo_status":"db","era":"慶応4","year":1868,"year_source":"db","year_min":1868,"year_max":1868,"year_label":null,"structure":"土蔵造２階建，瓦葺，建築面積20㎡","structure_material":"土蔵造２階建","registered":"1998.12.11(平成10.12.11)","register_no":"13 － 0050","desc":"隅田川沿いに位置するもと材木問屋の蔵。二階梁下端に「慶応四戊辰年八月吉日 三代目竹屋長四郎」等の墨書銘が認められる。震災と戦災をくぐりぬけてきた下町の土蔵として貴重。現在は喫茶店併設のギャラリーとして活用されている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000959"},{"id":"00012126","register_sub_id":"101","register_pk":"352925","name":"旧井阪屋本店河合ビル","kana":"きゅういさかやほんてんかわいびる","category":"産業3次","subcategory":"建築物","type_guess":"店舗","type_guess_confidence":"high","period":"昭和前","pref":"東京都","address":"東京都台東区雷門二丁目3-2","lat":35.709601,"lng":139.795933,"geo_status":"db","era":"昭和10年","year":1935,"year_source":"db","year_min":1935,"year_max":1935,"year_label":null,"structure":"鉄筋コンクリート造3階地下1階建、建築面積75㎡、塔屋付","structure_material":"鉄筋コンクリート造3階地下1階建","registered":"2018.03.27(平成30.03.27)","register_no":"13-393","desc":"浅草寺の参道に続く通りに建つ。鉄筋コンクリート造三階地下一階建で、塔屋を付ける。外観は一階正面のみ石貼とし、凹凸やレリーフを造り出し、屋上のパラペットを軒蛇腹のように張り出し、表情をつける。昭和初期の商業ビルとして貴重で地域に親しまれる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012126"},{"id":"00012127","register_sub_id":"101","register_pk":"352926","name":"旧井阪屋本店河合ビル稲荷社","kana":"きゅういさかやほんてんかわいびるいなりしゃ","category":"産業3次","subcategory":"建築物","type_guess":"店舗","type_guess_confidence":"high","period":"昭和前","pref":"東京都","address":"東京都台東区雷門二丁目3-10","lat":35.709931,"lng":139.789103,"geo_status":"db","era":"昭和初期／昭和22年頃移築","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和初期","structure":"木造平屋建、金属板葺、建築面積1.0㎡","structure_material":"木造平屋建","registered":"2018.03.27(平成30.03.27)","register_no":"13-394","desc":"敷地後方に東面して建つ。一・八メートル四方の切石基壇上に基礎石を据え、桁行一メートル、梁間一メートル、切妻造平入で正面を葺下し流造のようにみせる屋根形式。正面に両開格子戸をたてるのみで装飾を控えた外観で、屋敷構えに趣を添える小社である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012127"},{"id":"00008825","register_sub_id":"101","register_pk":"162268","name":"旧常盤家本館（石合家住宅主屋）","kana":"きゅうときわやほんかん（いしあいけじゅうたくしゅおく）","category":"産業3次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"昭和中","pref":"東京都","address":"東京都新宿区神楽坂3-2-41他","lat":35.70201935,"lng":139.74056375,"geo_status":"db","era":"昭和25年／昭和29年増築","year":1950,"year_source":"db","year_min":1950,"year_max":1950,"year_label":null,"structure":"木造2階建、瓦葺、建築面積219㎡","structure_material":"木造2階建","registered":"2011.10.28(平成23.10.28)","register_no":"13 － 0284","desc":"神楽坂界隈に位置する木造2階建で、建築面積219㎡。南面中央の坪庭をコの字型に囲む3棟からなり、唐破風を載せた庇付の玄関を北棟西面に付設。銘木を多用し、客室の障壁画や浴室のステインドグラスなど豊かに装飾される。近代待合の趣を伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008825"},{"id":"00007624","register_sub_id":"101","register_pk":"108606","name":"旧ほていや玩具店店舗","kana":"きゅうほていやがんぐてんてんぽ","category":"産業3次","subcategory":"建築物","type_guess":"店舗","type_guess_confidence":"high","period":"昭和前","pref":"東京都","address":"東京都青梅市仲町303-2","lat":35.789047,"lng":139.25731131,"geo_status":"db","era":"昭和前期／昭和40改修","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和前期","structure":"木造2階建、鉄板葺、建築面積47㎡","structure_material":"木造2階建","registered":"2009.04.28(平成21.04.28)","register_no":"13 － 0245","desc":"青梅街道に北面する木造２階建の店舗。１階を店舗、２階を客間とする。外壁正面は銅板張、側面は鉄板張で、正面２階にバルコニーを張り出し、人造石洗出し仕上げの円柱や手すりを設け、軒まわりやパラペットに装飾を凝らす。昭和戦前における商業建築の好例。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007624"},{"id":"00015295","register_sub_id":"101","register_pk":"532419","name":"旧宮脇ビル（川崎ブランドデザインビルヂング）","kana":"きゅうみやわきびる（かわさきぶらんどでざいんびるぢんぐ）","category":"産業3次","subcategory":"建築物","type_guess":"店舗","type_guess_confidence":"high","period":"昭和前","pref":"東京都","address":"東京都中央区銀座一丁目207","lat":35.673075,"lng":139.77056667,"geo_status":"db","era":"昭和7年／昭和17年増築、令和5年改修","year":1932,"year_source":"db","year_min":1932,"year_max":1932,"year_label":null,"structure":"鉄筋コンクリート造3階建、建築面積45㎡","structure_material":"鉄筋コンクリート造3階建","registered":"2025.03.13(令和7.03.13)","register_no":"13 - 0516","desc":"銀座昭和通りの角地に建つ商業ビル。間口四メートル、奥行九メートルで台形平面。西は鉄筋コンクリート造木造床で、東はラーメン構造で増築し一体化。縦長窓とタイル貼で全体を整える。関東大震災以降、銀座で隆盛した不燃化商業ビルの現存例として貴重。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00015295"},{"id":"00012298","register_sub_id":"101","register_pk":"531622","name":"喜代川店舗","kana":"きよかわてんぽ","category":"産業3次","subcategory":"建築物","type_guess":"店舗","type_guess_confidence":"high","period":"昭和前","pref":"東京都","address":"東京都中央区日本橋小網町10-5","lat":35.68268889,"lng":139.78082222,"geo_status":"db","era":"昭和2年頃／昭和40年代・平成25年・同27年改修","year":1927,"year_source":"db","year_min":1927,"year_max":1927,"year_label":null,"structure":"木造2階建、銅板葺一部瓦葺、建築面積107㎡","structure_material":"木造2階建","registered":"2018.05.10(平成30.05.10)","register_no":"13-404","desc":"人形町近傍のオフィス街にあり、路地に東面して建つ。寄棟造の平入で正面南端に切妻屋根の玄関を付け、背面に角屋を出す。一階には厨房・客席と居室、二階に座敷五室を設ける。開発著しい都心部で良質な伝統木造建築の姿を留める希少な店舗兼住宅。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012298"},{"id":"00015296","register_sub_id":"101","register_pk":"532420","name":"銀座大野屋店舗兼主屋","kana":"ぎんざおおのやてんぽけんおもや","category":"産業3次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"昭和中","pref":"東京都","address":"東京都中央区銀座五丁目202-13","lat":35.66965,"lng":139.76666667,"geo_status":"db","era":"昭和26年／昭和後期・平成13年改修","year":1951,"year_source":"db","year_min":1951,"year_max":1951,"year_label":null,"structure":"木造平屋一部2階建、鉄板葺、建築面積39㎡","structure_material":"木造平屋一部2階建","registered":"2025.03.13(令和7.03.13)","register_no":"13 - 0517","desc":"銀座の昭和通りと晴海通りの交差点に位置する足袋店。隅切りの角地形状に合わせた五角形平面に、平屋建の店舗と二階建の作業場兼住居を並べた変則的なつくり。正面にショーウインドー、内部に帳場を残す。戦災直後の銀座の景観を伝える貴重な木造商業建築。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00015296"},{"id":"00014141","register_sub_id":"101","register_pk":"508771","name":"銀座ライオンビル","kana":"ぎんざらいおんびる","category":"産業3次","subcategory":"建築物","type_guess":"店舗","type_guess_confidence":"high","period":"昭和前","pref":"東京都","address":"東京都中央区銀座七丁目1","lat":35.66916111,"lng":139.76323889,"geo_status":"db","era":"昭和9年／昭和14年・同54年改修","year":1934,"year_source":"db","year_min":1934,"year_max":1934,"year_label":null,"structure":"鉄筋コンクリート造地上6階地下1階建、建築面積512㎡、塔屋付","structure_material":"鉄筋コンクリート造地上6階地下1階建","registered":"2022.02.17(令和4.02.17)","register_no":"13-0459","desc":"銀座７丁目に建つ鉄骨鉄筋コンクリート造地下１階地上６階建。外観は１階やパラペットにライト調意匠を残す。内装は６階ホールの他、１階ビヤホールが白眉でタイル張壁面に梁型等の装飾を施し、圧巻のガラスモザイク壁画を飾る。我国ビヤホールの一大傑作。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014141"},{"id":"00000639","register_sub_id":"101","register_pk":"101629","name":"さかえビル","kana":"さかえびる","category":"産業3次","subcategory":"建築物","type_guess":"店舗","type_guess_confidence":"high","period":"昭和前","pref":"東京都","address":"東京都文京区本郷3-38-10","lat":35.70741581,"lng":139.76286532,"geo_status":"db","era":"昭和9","year":1934,"year_source":"db","year_min":1934,"year_max":1934,"year_label":null,"structure":"鉄筋コンクリート造地下１階地上４階建，建築面積105㎡","structure_material":"鉄筋コンクリート造地下１階地上４階建","registered":"1998.09.02(平成10.09.02)","register_no":"13 － 0020","desc":"薬学博士を施主とする薬学研究所を兼ねた事務所ビル。角地に建ち，隅切りの面に正面性をもたせたファサード構成をとる。スクラッチタイル貼りで，要所にテラコッタの装飾を配したアール・デコ建築の佳品となっている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000639"},{"id":"00003198","register_sub_id":"101","register_pk":"104188","name":"進開屋","kana":"しんかいや","category":"産業3次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"東京都","address":"東京都文京区千石2-30-6","lat":35.72525914,"lng":139.74155129,"geo_status":"db","era":"昭和初期","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和初期","structure":"木造2階建、瓦葺、建築面積52㎡","structure_material":"木造2階建","registered":"2003.03.18(平成15.03.18)","register_no":"13 － 0142","desc":"そば屋の店舗として建築された。１階前半土間に卓・椅子を置いて客席とし，奥を土間と板間に分け調理場とする。客席土間から上がる２階は前後に客座敷２室を配す。立ちの高い外観は１階に出格子を設け，２階は軒をせがい，窓に透かし板の高欄を付けて整える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003198"},{"id":"00015414","register_sub_id":"101","register_pk":"533429","name":"新潮社倉庫","kana":"しんちょうしゃそうこ","category":"産業3次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"high","period":"昭和中","pref":"東京都","address":"東京都新宿区矢来町71-8他","lat":35.70331111,"lng":139.73311111,"geo_status":"db","era":"昭和34年／昭和41年増築","year":1959,"year_source":"db","year_min":1959,"year_max":1959,"year_label":null,"structure":"鉄筋コンクリート造5階建、建築面積471㎡、外階段及びスロープ付","structure_material":"鉄筋コンクリート造5階建","registered":"2025.08.06(令和7.08.06)","register_no":"13 - 0523","desc":"本館と並列して建つ倉庫。鉄筋コンクリート造５階建で、梁を密に配した五百万冊分の収容スペースの他、事務室、昇降機、荷捌場を備え、納品から出庫までの新刊物流拠点であった。階数が異なる本館と高さ、外観を揃え、深い庇を連続し長大な沿道景観をつくる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00015414"},{"id":"00015413","register_sub_id":"101","register_pk":"533428","name":"新潮社本館","kana":"しんちょうしゃほんかん","category":"産業3次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和中","pref":"東京都","address":"東京都新宿区矢来町71-10他","lat":35.70294722,"lng":139.73304722,"geo_status":"db","era":"昭和32年／昭和41年増築、平成4年改修","year":1957,"year_source":"db","year_min":1957,"year_max":1957,"year_label":null,"structure":"鉄筋コンクリート造地上4階地下1階建、建築面積791㎡","structure_material":"鉄筋コンクリート造地上4階地下1階建","registered":"2025.08.06(令和7.08.06)","register_no":"13 - 0522","desc":"神楽坂に近い高台に建つ出版社の本社ビル。鉄筋コンクリート造、釉薬タイル貼の簡明かつ格調高い外観と、古今東西の人類の文字を刻む壁面レリーフなど社員が関わりデザインした内部造作が特徴。我が国有数の出版・印刷製本業集積地を代表するオフィスビル。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00015413"},{"id":"00012300","register_sub_id":"101","register_pk":"531624","name":"新富町躍金楼店舗","kana":"しんとみちょうてっきんろうてんぽ","category":"産業3次","subcategory":"建築物","type_guess":"店舗","type_guess_confidence":"high","period":"昭和中","pref":"東京都","address":"東京都中央区新富一丁目11-3他","lat":35.67211667,"lng":139.77466944,"geo_status":"db","era":"昭和24年頃／昭和30年代増築、平成24年改修","year":1949,"year_source":"db","year_min":1949,"year_max":1949,"year_label":null,"structure":"木造2階建、瓦葺、建築面積186㎡、塀付","structure_material":"木造2階建","registered":"2018.05.10(平成30.05.10)","register_no":"13-406","desc":"旧花街にある店舗兼住宅で、街路に南面して建つ。切妻造妻入の両側に下屋を出し、東側面に居室が別棟で取付く。内部の改変があるが、外観は伝統木造の料亭の姿を留め、正面の僅かな空間に前庭を取って門塀を構えるなど、地域の歴史的景観を伝える希少な建物。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012300"},{"id":"00001563","register_sub_id":"101","register_pk":"102553","name":"すぺーす小倉屋蔵","kana":"すぺーすおぐらやくら","category":"産業3次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"大正","pref":"東京都","address":"東京都台東区谷中七丁目207-2","lat":35.72472439,"lng":139.76890486,"geo_status":"db","era":"大正5","year":1916,"year_source":"db","year_min":1916,"year_max":1916,"year_label":null,"structure":"土蔵造3階建、瓦葺、建築面積20㎡","structure_material":"土蔵造3階建","registered":"2000.04.28(平成12.04.28)","register_no":"13 － 0078","desc":"小倉屋三代目平三郎が店舗に隣接して建てた質蔵。表通りに西妻を向け，東妻を戸口とし庇が附属する。梁間が二間と狭いに関わらず三階建とする本格的な土蔵造で，近在でもひときわ高さが際だった存在である。棟札にも富士山の眺めを詠った句を記す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001563"},{"id":"00001562","register_sub_id":"101","register_pk":"102552","name":"すぺーす小倉屋店舗","kana":"すぺーすおぐらやてんぽ","category":"産業3次","subcategory":"建築物","type_guess":"店舗","type_guess_confidence":"high","period":"江戸","pref":"東京都","address":"東京都台東区谷中七丁目207-2","lat":35.72465226,"lng":139.76893003,"geo_status":"db","era":"江戸末期","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"木造2階建、スレート葺、建築面積41㎡","structure_material":"木造2階建","registered":"2000.04.28(平成12.04.28)","register_no":"13 － 0077","desc":"感応寺（後の天王寺）の門前町で享保年間から代々質屋を営んだ商家で，屋号を小倉屋という。店舗は間口三間の中二階建の町家であり，表通りからやや後退して建つ。大戸口の構えを良く残し，通り庭に面する八畳の帳場を現在ギャラリーとする。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001562"},{"id":"00007882","register_sub_id":"101","register_pk":"108862","name":"西郊ロッヂング","kana":"せいこうろっぢんぐ","category":"産業3次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"東京都","address":"東京都杉並区荻窪3-63","lat":35.70302366,"lng":139.62530608,"geo_status":"db","era":"昭和13／昭和中期・平成13改修","year":1938,"year_source":"db","year_min":1938,"year_max":1938,"year_label":null,"structure":"木造2階建、瓦葺一部銅板葺、建築面積145㎡","structure_material":"木造2階建","registered":"2009.11.02(平成21.11.02)","register_no":"13-0253","desc":"本館西側に隣接して、敷地の北西角に沿うようにＬ字形に建つ。木造２階建、桟瓦一部銅板葺、建築面積１４５㎡。１３室を有する集合住宅。北西角を曲壁面とし、その上部に銅板葺ドーム屋根を載せる独特の外観は、ベージュの色調と調和し、親しみを感じさせる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007882"},{"id":"00002614","register_sub_id":"101","register_pk":"103604","name":"太洋ビルディング（丸石ビルディング）","kana":"たいようびるでぃんぐ（まるいしびるでぃんぐ）","category":"産業3次","subcategory":"建築物","type_guess":"店舗","type_guess_confidence":"high","period":"昭和前","pref":"東京都","address":"東京都千代田区鍛冶町1-10-4","lat":35.690285,"lng":139.772751,"geo_status":"db","era":"昭和6／昭和8増築","year":1931,"year_source":"db","year_min":1931,"year_max":1931,"year_label":null,"structure":"鉄骨鉄筋コンクリート造6階地下1階、建築面積555㎡","structure_material":"鉄骨鉄筋コンクリート造6階地下1階","registered":"2002.02.14(平成14.02.14)","register_no":"13 － 0119","desc":"中央区との区境，旧龍閑川沿いに立地するオフィスビル。石貼の一階部分を除き，主にスクラッチタイル貼の外装とし，６階胴蛇腹と頂部のテラコッタ製蛇腹で外観に変化を与える。１階開口部のアーチ迫石や付柱の柱頭を動植物のレリーフで飾る。山下寿郎設計。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002614"},{"id":"00008657","register_sub_id":"101","register_pk":"149378","name":"高橋建築事務所社屋","kana":"たかはしけんちくじむしょしゃおく","category":"産業3次","subcategory":"建築物","type_guess":"事務所","type_guess_confidence":"high","period":"昭和前","pref":"東京都","address":"東京都新宿区矢来町114","lat":35.70392397,"lng":139.73468167,"geo_status":"db","era":"昭和29年","year":1954,"year_source":"converted","year_min":1954,"year_max":1954,"year_label":null,"structure":"木造2階建、瓦葺、建築面積42㎡","structure_material":"木造2階建","registered":"2011.07.25(平成23.07.25)","register_no":"13 － 0280","desc":"早稲田通りに南面する敷地に建つ。切妻造桟瓦葺の主棟の西北に切妻屋根を突出する木造2階建。ハーフティンバー風の外観で、通り側には出窓を設ける。内部は方杖や梁など木部を現す。イギリス田舎家風の穏やかな外観が神楽坂界隈の景観に潤いを与える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008657"},{"id":"00002755","register_sub_id":"101","register_pk":"103745","name":"棚澤書店","kana":"たなざわしょてん","category":"産業3次","subcategory":"建築物","type_guess":"店舗","type_guess_confidence":"low","period":"明治","pref":"東京都","address":"東京都文京区本郷6-18-12","lat":35.713577,"lng":139.759064,"geo_status":"db","era":"明治期","year":1890,"year_source":"estimated","year_min":1868,"year_max":1912,"year_label":"明治期","structure":"木造2階建、瓦葺、建築面積29㎡","structure_material":"木造2階建","registered":"2002.06.25(平成14.06.25)","register_no":"13 － 0127","desc":"本郷通りを挟んだ東京大学正門前にあり，２軒長屋を用いた店舗である。東を正面とし，２階建，切妻造・桟瓦葺，平入，正面半間下屋庇付の形式で，軒は出桁造である。東大周辺に形成された近代商家の町並景観を伝える建物として欠かせない存在となっている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002755"},{"id":"00004529","register_sub_id":"101","register_pk":"105519","name":"玉置文治郎ビル","kana":"たまおきぶんじろうびる","category":"産業3次","subcategory":"建築物","type_guess":"店舗","type_guess_confidence":"high","period":"昭和前","pref":"東京都","address":"東京都中央区東日本橋2-16-8","lat":35.69452538,"lng":139.78556086,"geo_status":"db","era":"昭和4","year":1929,"year_source":"db","year_min":1929,"year_max":1929,"year_label":null,"structure":"鉄筋コンクリート造地上4階地下1階建、建築面積97㎡","structure_material":"鉄筋コンクリート造地上4階地下1階建","registered":"2005.02.09(平成17.02.09)","register_no":"13 － 0183","desc":"靖国通り沿いに北面して建つ，鉄筋コンクリート造地上４階地下１階建の薬品問屋店舗兼住宅。震災復興商業ビルのひとつで，筋面タイルやテラコッタを用い，幾何学形を装飾に取り込んだ外観は，昭和初期における建築意匠の特徴をよく伝える。設計は森山松之助。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004529"},{"id":"00013971","register_sub_id":"101","register_pk":"508231","name":"茶寮一松表門及び塀","kana":"ちゃりょういちまつおもてもんおよびへい","category":"産業3次","subcategory":"その他工作物","type_guess":"塀・門","type_guess_confidence":"high","period":"昭和中","pref":"東京都","address":"東京都台東区雷門一丁目47-1他","lat":35.71077222,"lng":139.79336389,"geo_status":"db","era":"昭和35年","year":1960,"year_source":"db","year_min":1960,"year_max":1960,"year_label":null,"structure":"門 木造、瓦葺一部銅板葺、間口3.3m 塀 コンクリートブロック造、瓦葺、延長37m","structure_material":"門 木造","registered":"2021.10.14(令和3.10.14)","register_no":"13 - 0456","desc":"敷地南・東辺を区画する塀と、隅切部に建つ門。門は切妻造桟瓦葺、軒銅板葺の腕木門で、桁や腕木を塗込め、柱を重厚なタイル貼、板扉を吊り、左脇に潜戸を設ける。塀はコンクリートブロック造、腰を鉄平石貼、桟瓦葺。落着いた雰囲気で料亭に相応しい。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013971"},{"id":"00013970","register_sub_id":"101","register_pk":"508230","name":"茶寮一松店舗及び住居","kana":"ちゃりょういちまつてんぽおよびじゅうきょ","category":"産業3次","subcategory":"建築物","type_guess":"店舗","type_guess_confidence":"high","period":"昭和中","pref":"東京都","address":"東京都台東区雷門一丁目47-1","lat":35.71086111,"lng":139.79318889,"geo_status":"db","era":"昭和35年／令和2年改修","year":1960,"year_source":"db","year_min":1960,"year_max":1960,"year_label":null,"structure":"木造二階一部地下一階建、鉄板葺、建築面積389㎡","structure_material":"木造二階一部地下一階建","registered":"2021.10.14(令和3.10.14)","register_no":"13 - 0455","desc":"浅草雷門通の一筋南に位置する入母屋造料亭。敷地南の前庭を囲むＬ字形平面で、入隅を玄関、南面して座敷を並べ、北に住居部を配す。二階は三間続きの大広間を配し、床の間と舞台を設け、宴席の時代相を示す。随所に銘木や彫刻を飾る数寄屋意匠の料亭建築。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013970"},{"id":"00007018","register_sub_id":"101","register_pk":"108000","name":"燕湯","kana":"つばめゆ","category":"産業3次","subcategory":"建築物","type_guess":"煙突","type_guess_confidence":"low","period":"昭和中","pref":"東京都","address":"東京都台東区上野3-9-2","lat":35.705482,"lng":139.772903,"geo_status":"db","era":"昭和25","year":1950,"year_source":"db","year_min":1950,"year_max":1950,"year_label":null,"structure":"木造2階建、瓦葺及び鉄板葺、建築面積205㎡、煙突及び地下燃料庫付","structure_material":"木造2階建","registered":"2008.04.18(平成20.04.18)","register_no":"13 － 0228","desc":"道路に西面して建つ間口５間半奥行４間の木造２階建で、背面に平屋建浴室、ＲＣ造釜場を付設。正面中央に入母屋屋根の下足場を付け、１階は男女の脱衣場、２階は座敷とする。浴室は梁行中央２間半を建ち上げ湯気抜窓を設ける。ＲＣ造煙突が銭湯を象徴付ける。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007018"},{"id":"00014570","register_sub_id":"101","register_pk":"515112","name":"手焼せんべい嵯峨の家店舗","kana":"てやきせんべいさがのやてんぽ","category":"産業3次","subcategory":"建築物","type_guess":"店舗","type_guess_confidence":"high","period":"明治","pref":"東京都","address":"東京都台東区谷中六丁目14","lat":35.72141389,"lng":139.77063611,"geo_status":"db","era":"明治後期／昭和48年頃改修","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治後期","structure":"木造2階建、瓦葺、建築面積32㎡","structure_material":"木造2階建","registered":"2023.08.07(令和5.08.07)","register_no":"13 - 0485","desc":"谷中寺町の通りに東面する煎餅店。切妻造平入桟瓦葺の二階建店舗兼住居。出桁造の伝統的な町家を改修した看板建築で、一階表を土間ミセ、奥は板敷の作業場とし、床下に炭入付、煎餅焼の窯を置く。二階は三室と増築部分で構成、西室では煎餅干しの作業を行う。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014570"},{"id":"00009591","register_sub_id":"101","register_pk":"194587","name":"東京タワー","kana":"とうきょうたわー","category":"産業3次","subcategory":"その他工作物","type_guess":"その他","type_guess_confidence":"low","period":"昭和中","pref":"東京都","address":"東京都港区芝公園4-407-6","lat":35.65857144,"lng":139.74544621,"geo_status":"db","era":"昭和33／昭和42改修","year":1958,"year_source":"db","year_min":1958,"year_max":1958,"year_label":null,"structure":"鉄骨造、高さ333m、脚間80m、展望室付","structure_material":"鉄骨造","registered":"2013.06.21(平成25.06.21)","register_no":"13 － 0295","desc":"芝公園に位置する鉄骨造の集約電波塔。二層の大展望台と一層の特別展望台を持つ。高さ三三三メートルと、自立式鉄塔としてはエッフェル塔を凌ぎ、当時世界最高を実現した。戦後日本の復興の象徴として、また高度経済成長の原点として、国民に広く親しまれる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009591"},{"id":"00008654","register_sub_id":"101","register_pk":"149375","name":"虎ノ門大坂屋砂場店舗","kana":"とらのもんおおさかやすなばてんぽ","category":"産業3次","subcategory":"建築物","type_guess":"塀・門","type_guess_confidence":"high","period":"大正","pref":"東京都","address":"東京都港区虎ノ門1-21","lat":35.66822157,"lng":139.75069123,"geo_status":"db","era":"大正12年／平成6年・平成19年改修","year":1923,"year_source":"converted","year_min":1923,"year_max":1923,"year_label":null,"structure":"木造2階建、瓦葺、建築面積70㎡","structure_material":"木造2階建","registered":"2011.07.25(平成23.07.25)","register_no":"13 － 0277","desc":"交差点の北西角地に位置する。木造2階建、角地にあわせたＬ字型を基本に隅を斜めに削る。切妻造桟瓦葺とし、隅には千鳥破風を飾る。外壁は下見板張で、小壁を漆喰で仕上げる。2階は座敷で開口部には欄干を出す。町のランドマークとして親しまれる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008654"},{"id":"00008264","register_sub_id":"101","register_pk":"133906","name":"中江店舗","kana":"なかえてんぽ","category":"産業3次","subcategory":"建築物","type_guess":"店舗","type_guess_confidence":"high","period":"大正","pref":"東京都","address":"東京都台東区日本堤1-208-3","lat":35.725135,"lng":139.79704591,"geo_status":"db","era":"大正13年","year":1924,"year_source":"db","year_min":1924,"year_max":1924,"year_label":null,"structure":"木造2階建、瓦葺、建築面積55㎡","structure_material":"木造2階建","registered":"2010.09.10(平成22.09.10)","register_no":"13 － 0263","desc":"土手通りに西面して店を開く。桁行５．９ｍ梁間１０ｍの木造２階建。１、２階ともに座敷とし、２階は壁に腰板を張り、欄間には竹の組子に松竹梅と桜をあしらう。街路に平行する南北棟の切妻造桟瓦葺。熨斗瓦を高く積み、建ちの高い表構えをつくる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008264"},{"id":"00012128","register_sub_id":"101","register_pk":"352927","name":"難波商店店舗兼主屋","kana":"なんばしょうてんてんぽけんしゅおく","category":"産業3次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"昭和前","pref":"東京都","address":"東京都台東区寿二丁目6-4他","lat":35.709931,"lng":139.789103,"geo_status":"db","era":"昭和4年頃／昭和43年増築、昭和52年改修","year":1929,"year_source":"db","year_min":1929,"year_max":1929,"year_label":null,"structure":"鉄筋コンクリート造3階地下1階建、建築面積74㎡、塔屋付","structure_material":"鉄筋コンクリート造3階地下1階建","registered":"2018.03.27(平成30.03.27)","register_no":"13-395","desc":"浅草通りに面する角地に建つ。鉄筋コンクリート造で一階を店舗、地下一階と二階を倉庫、三階を居室とする。外壁は色モルタル塗で、縦長窓と丸窓を開き、緑色の瓦や高欄を廻し意匠性に富む。塔屋は反りの強い屋根を二重に架け、独創的な外観を形成している。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012128"},{"id":"00003074","register_sub_id":"101","register_pk":"104064","name":"花重店舗","kana":"はなじゅうてんぽ","category":"産業3次","subcategory":"建築物","type_guess":"店舗","type_guess_confidence":"high","period":"明治","pref":"東京都","address":"東京都台東区谷中七丁目311","lat":35.72359807,"lng":139.77017466,"geo_status":"db","era":"明治10","year":1877,"year_source":"db","year_min":1877,"year_max":1877,"year_label":null,"structure":"木造2階建、瓦葺、建築面積37㎡","structure_material":"木造2階建","registered":"2003.01.31(平成15.01.31)","register_no":"13 － 0138","desc":"谷中墓地開設とほぼ同時期に開業した生花問屋。明治１０年に前身建物を背面側に曳屋し，木造２階建の店舗兼居室を建てる。１階は店舗で，現在は花屋を営み，２階は３室に区切って畳敷の居室としている。江戸・明治期の谷中の風致を今に伝える建築である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003074"},{"id":"00003394","register_sub_id":"101","register_pk":"104384","name":"ハリオグラスビル","kana":"はりおぐらすびる","category":"産業3次","subcategory":"建築物","type_guess":"店舗","type_guess_confidence":"high","period":"昭和前","pref":"東京都","address":"東京都中央区日本橋富沢町9-3","lat":35.68887617,"lng":139.78190196,"geo_status":"db","era":"昭和7","year":1932,"year_source":"db","year_min":1932,"year_max":1932,"year_label":null,"structure":"鉄筋コンクリート造地下1階地上3階建、建築面積394㎡","structure_material":"鉄筋コンクリート造地下1階地上3階建","registered":"2003.07.01(平成15.07.01)","register_no":"13 － 0148","desc":"北西角の角切り部に営業室玄関を設け，北及び西面に溝彫を施したコリント式大オーダーを廻す。銀行支店建築の好例で，設計は川崎貯蓄銀行建築課，施工は竹中工務店。現在は耐熱ガラス食器会社のショールームを兼ねた本社ビルとして活用されている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003394"},{"id":"00001249","register_sub_id":"101","register_pk":"102239","name":"はん亭","kana":"はんてい","category":"産業3次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"大正","pref":"東京都","address":"東京都文京区根津2-12-15","lat":35.71732631,"lng":139.76611242,"geo_status":"db","era":"大正6","year":1917,"year_source":"db","year_min":1917,"year_max":1917,"year_label":null,"structure":"木造３階建，瓦葺，建築面積36㎡","structure_material":"木造３階建","registered":"1999.08.23(平成11.08.23)","register_no":"13 － 0056","desc":"不忍通りと一本東側の小路に挟まれた敷地の小路側角地に建つ。木造３階建、瓦葺寄棟屋根のもと店舗建築。ほぼ同面積、同高の階を三層に重ねたせいの高い町屋で、根津地区のランドマークとして知られる。現在は内部を改装して串揚屋になっている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001249"},{"id":"00001761","register_sub_id":"101","register_pk":"102751","name":"鳳明館本館","kana":"ほうめいかんほんかん","category":"産業3次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"東京都","address":"東京都文京区本郷五丁目426他","lat":35.71120335,"lng":139.75626941,"geo_status":"db","era":"明治30代／昭和初期改造","year":1897,"year_source":"converted","year_min":1897,"year_max":1897,"year_label":null,"structure":"木造地上2階地下1階建、瓦葺、建築面積591㎡","structure_material":"木造地上2階地下1階建","registered":"2000.09.26(平成12.09.26)","register_no":"13 － 0087","desc":"木造２階建の近代和風建築。下宿屋として建設されたが，昭和初期に下宿屋兼旅館に改造し、さらに昭和２０年に旅館建築に模様替えした。各室毎に異なったつくりで，部屋の銘木に合わせた部屋名とする。下宿・旅館が多かった本郷地区の歴史的な景観を伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001761"},{"id":"00000525","register_sub_id":"101","register_pk":"101515","name":"堀商店","kana":"ほりしょうてん","category":"産業3次","subcategory":"建築物","type_guess":"店舗","type_guess_confidence":"high","period":"昭和前","pref":"東京都","address":"東京都港区新橋2-5-2","lat":35.66794918,"lng":139.75614879,"geo_status":"db","era":"昭和7","year":1932,"year_source":"db","year_min":1932,"year_max":1932,"year_label":null,"structure":"鉄筋コンクリート造４階建塔屋付，建築面積173㎡","structure_material":"鉄筋コンクリート造４階建塔屋付","registered":"1998.04.21(平成10.04.21)","register_no":"13 － 0009","desc":"新橋駅に近い角地に建つ建築金物を扱う商店のビル。鉄筋コンクリート造４階建で，西端に垂直線を強調した窓を持つ階段室と塔屋を設ける。軒廻りの装飾が特異で，スクラッチタイル貼りの外壁，水平線を強調した窓廻りに時代の特徴がよくあらわれている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000525"},{"id":"00001657","register_sub_id":"101","register_pk":"102647","name":"松本家住宅主屋","kana":"まつもとけじゅうたくしゅおく","category":"産業3次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"昭和前","pref":"東京都","address":"東京都千代田区神田多町2-9","lat":35.69429638,"lng":139.76894818,"geo_status":"db","era":"昭和6","year":1931,"year_source":"db","year_min":1931,"year_max":1931,"year_label":null,"structure":"木造3階建、瓦葺、建築面積137㎡","structure_material":"木造3階建","registered":"2000.04.28(平成12.04.28)","register_no":"13 － 0082","desc":"神田多町問屋街に残る震災復興町家で、多町大通りに面した角地に東面して建つ。木造３階建、切妻造、平入で、正面は出桁造の構えをとり、北妻面は窓の少ない防火に配慮した造りとする。東京の下町における震災復興期の和風町家として貴重である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001657"},{"id":"00012299","register_sub_id":"101","register_pk":"531623","name":"繭山龍泉堂店舗","kana":"まゆやまりゅうせんどうてんぽ","category":"産業3次","subcategory":"建築物","type_guess":"店舗","type_guess_confidence":"high","period":"昭和中","pref":"東京都","address":"東京都中央区京橋二丁目5-60他","lat":35.67613889,"lng":139.77125278,"geo_status":"db","era":"昭和35年／昭和58年・平成29年改修","year":1960,"year_source":"db","year_min":1960,"year_max":1960,"year_label":null,"structure":"鉄筋コンクリート造3階一部4階建地下1階、建築面積191㎡","structure_material":"鉄筋コンクリート造3階一部4階建地下1階","registered":"2018.05.10(平成30.05.10)","register_no":"13-405","desc":"美術商が集まる京橋二丁目の一角にある店舗兼住宅。設計は東畑謙三による。通りに面した北面と東面は錆付きの由来石を額縁状に廻し、壁面を弁柄入黒漆喰で仕上げるなど骨董美術を意識した意匠でまとめる。目覚ましい都市の戦後復興を彩った商業建築の好例。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012299"},{"id":"00014143","register_sub_id":"101","register_pk":"508773","name":"安与ビル","kana":"やすよびる","category":"産業3次","subcategory":"建築物","type_guess":"店舗","type_guess_confidence":"high","period":"昭和後","pref":"東京都","address":"東京都新宿区新宿三丁目114-13","lat":35.69060833,"lng":139.70131111,"geo_status":"db","era":"昭和43年","year":1968,"year_source":"db","year_min":1968,"year_max":1968,"year_label":null,"structure":"鉄骨鉄筋コンクリート造地上9階地下2階建、建築面積416㎡、塔屋付","structure_material":"鉄骨鉄筋コンクリート造地上9階地下2階建","registered":"2022.02.17(令和4.02.17)","register_no":"13-0461","desc":"新宿東口に建つ。鉄骨鉄筋コンクリート造地下２階地上９階建。背面にＬ字型のサービス部分を立上げ、入隅に、竪格子状ルーバーを付けた八角形平面を各階で角度を変えて積層させる、特異ながら品のある外観意匠。内装は残月亭写し始め、谷口吉郎円熟期の逸品。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014143"},{"id":"00001500","register_sub_id":"101","register_pk":"102490","name":"萬屋酒店","kana":"よろずやさけてん","category":"産業3次","subcategory":"建築物","type_guess":"店舗","type_guess_confidence":"low","period":"明治","pref":"東京都","address":"東京都大田区池上4-23-6","lat":35.575211,"lng":139.704681,"geo_status":"db","era":"明治8","year":1875,"year_source":"db","year_min":1875,"year_max":1875,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積106㎡","structure_material":"木造平屋建","registered":"2000.02.15(平成12.02.15)","register_no":"13 － 0071","desc":"池上本門寺参道沿いの現在地に茶屋を営んだのが当家のはじまりと伝える。つし二階建，出桁造りの江戸時代以来の町家の形式で，上げ下げ戸を含め旧状を良く残す。門前町の代表的な建物のひとつであり，ランドマークとして親しまれている。棟梁は加藤甚五郎。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001500"},{"id":"00007881","register_sub_id":"101","register_pk":"108861","name":"旅館西郊本館","kana":"りょかんせいこうほんかん","category":"産業3次","subcategory":"建築物","type_guess":"旅館","type_guess_confidence":"high","period":"昭和前","pref":"東京都","address":"東京都杉並区荻窪3-63","lat":35.70285511,"lng":139.62549601,"geo_status":"db","era":"昭和6／昭和中期改修","year":1931,"year_source":"db","year_min":1931,"year_max":1931,"year_label":null,"structure":"木造2階建、スレート葺一部鉄板葺及び瓦葺、建築面積473㎡","structure_material":"木造2階建","registered":"2009.11.02(平成21.11.02)","register_no":"13-0252","desc":"敷地東側の中庭を囲むように「コ」の字形に建つ。木造２階建、スレート一部鉄板及び桟瓦葺、建築面積４７３㎡。１階は玄関や広間、厨房など、２階には宿泊室を配する。ベージュ色のモルタル洗出し仕上げの大壁造とする外観は落ち着きのある街路景観をつくる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007881"},{"id":"00011906","register_sub_id":"101","register_pk":"211071","name":"五十嵐商店第一号倉庫","kana":"いがらししょうてんだいいちごうそうこ","category":"産業3次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"high","period":"昭和前","pref":"神奈川県","address":"神奈川県秦野市本町二丁目2687","lat":35.372095,"lng":139.229047,"geo_status":"db","era":"昭和初期","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和初期","structure":"木造2階建、建築面積27㎡","structure_material":"木造2階建","registered":"2017.10.27(平成29.10.27)","register_no":"14-245","desc":"敷地後方中央に南面する。桁行三間、梁間二間、切妻造、平入。外壁をモルタル仕上げとし、扉口はモルタル仕上げの片引戸、内板戸、格子戸片引きで、二階南面に鳥居枠の窓を穿つ。小屋組は登梁形式。外壁に目地を刻み石造風に仕上げ、敷地後方の景観を形作る。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011906"},{"id":"00011908","register_sub_id":"101","register_pk":"211073","name":"五十嵐商店第三号倉庫","kana":"いがらししょうてんだいさんごうそうこ","category":"産業3次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"high","period":"昭和前","pref":"神奈川県","address":"神奈川県秦野市本町二丁目2687-1","lat":35.372043,"lng":139.229089,"geo_status":"db","era":"昭和初期","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和初期","structure":"木造平屋建、建築面積2.2㎡","structure_material":"木造平屋建","registered":"2017.10.27(平成29.10.27)","register_no":"14-247","desc":"第一号倉庫の南に建つ。間口一・二メートル、奥行一・八メートル。切妻造とするが、軒の出は造らず、壁から屋根までモルタルで塗込め、正面のみ水切のため、妻壁を迫出す。小屋組は、梁を架け、棟木を受ける簡素な構造。小規模ながら敷地景観を構成する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011908"},{"id":"00011907","register_sub_id":"101","register_pk":"211072","name":"五十嵐商店第二号倉庫","kana":"いがらししょうてんだいにごうそうこ","category":"産業3次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"high","period":"昭和前","pref":"神奈川県","address":"神奈川県秦野市本町二丁目2687","lat":35.372132,"lng":139.229109,"geo_status":"db","era":"昭和初期","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和初期","structure":"木造2階建、建築面積27㎡","structure_material":"木造2階建","registered":"2017.10.27(平成29.10.27)","register_no":"14-246","desc":"店舗兼主屋と第一号倉庫との間に南面する。桁行三間、梁間二間、切妻造、平入。外壁はモルタル仕上げで、腰まで目地を刻む。扉口はモルタル仕上げの両開戸で、二階南面に引分戸の窓を穿つ。小屋組はキングポストトラスで、新たな技法を取り入れた倉庫。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011907"},{"id":"00011909","register_sub_id":"101","register_pk":"211074","name":"五十嵐商店第四号倉庫及び第五号倉庫","kana":"いがらししょうてんだいよんごうそうこおよびだいごごうそうこ","category":"産業3次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"high","period":"昭和前","pref":"神奈川県","address":"神奈川県秦野市本町二丁目2687","lat":35.372184,"lng":139.228998,"geo_status":"db","era":"昭和12年頃","year":1937,"year_source":"db","year_min":1937,"year_max":1937,"year_label":null,"structure":"木造平屋建、建築面積106㎡","structure_material":"木造平屋建","registered":"2017.10.27(平成29.10.27)","register_no":"14-248","desc":"敷地北西にあり南面する。桁行四間、梁間三間の二棟に切妻造の屋根を架け、正面に下屋庇を付ける。外壁は四隅の柱や鉢巻にモルタル仕上げを見せる。内部は、中央両端半間に間仕切壁を設けるほかは一室で、小屋組はキングポストトラスとする大型倉庫。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011909"},{"id":"00011905","register_sub_id":"101","register_pk":"211070","name":"五十嵐商店店舗兼主屋","kana":"いがらししょうてんてんぽけんしゅおく","category":"産業3次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"昭和前","pref":"神奈川県","address":"神奈川県秦野市本町二丁目2687","lat":35.372165,"lng":139.229201,"geo_status":"db","era":"昭和3年／昭和11年頃増築","year":1928,"year_source":"db","year_min":1928,"year_max":1928,"year_label":null,"structure":"木造3階建、建築面積122㎡、門柱付","structure_material":"木造3階建","registered":"2017.10.27(平成29.10.27)","register_no":"14-244","desc":"秦野市中心部に東面する。木造三階建で、外壁は正面をモルタル洗出し、側背面をモルタル仕上げと異にし、柱形や柱頭飾に意匠を凝らす。一階は店舗部で広い土間と畳敷のミセ・帳場を配し、二、三階は居室部で応接間を設ける。古典様式風の外観で親しまれる商店。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011905"},{"id":"00009929","register_sub_id":"101","register_pk":"196076","name":"伊藤屋旅館奥棟","kana":"いとうやりょかんおくとう","category":"産業3次","subcategory":"建築物","type_guess":"旅館","type_guess_confidence":"high","period":"大正","pref":"神奈川県","address":"神奈川県足柄下郡湯河原町宮上字橋下484-1他","lat":35.14646586,"lng":139.07442493,"geo_status":"db","era":"大正前期","year":1917,"year_source":"estimated","year_min":1912,"year_max":1918,"year_label":"大正前期","structure":"木造2階建、瓦葺、建築面積50㎡","structure_material":"木造2階建","registered":"2014.04.25(平成26.04.25)","register_no":"14 － 0186","desc":"本館北側の傾斜地に建つ。木造二階建、入母屋造桟瓦葺で、窓上に庇を廻らす。上下階とも客室数室を配し、本館同様、南縁の全開口にガラス窓をたてる。内部造作では違棚やトコ脇にも窓を開け、壁に山形窓を穿つなど通風採光に配慮し、各部意匠も洗練される。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009929"},{"id":"00009928","register_sub_id":"101","register_pk":"196075","name":"伊藤屋旅館本館","kana":"いとうやりょかんほんかん","category":"産業3次","subcategory":"建築物","type_guess":"旅館","type_guess_confidence":"high","period":"大正","pref":"神奈川県","address":"神奈川県足柄下郡湯河原町宮上字橋下484-1他","lat":35.14639548,"lng":139.07423103,"geo_status":"db","era":"大正15","year":1926,"year_source":"db","year_min":1926,"year_max":1926,"year_label":null,"structure":"木造2階建、瓦葺、建築面積119㎡","structure_material":"木造2階建","registered":"2014.04.25(平成26.04.25)","register_no":"14 － 0185","desc":"川の北岸に南面して建つ木造二階建の旅館。入母屋造桟瓦葺で上下階に庇を廻らし、二階縁の南面では、腰部や欄間にもガラス窓をたてて開放的な形式とする。客室の内部造作も座敷飾など繊細な意匠になる。近代の湯河原温泉整備期における初期の旅館建築である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009928"},{"id":"00009930","register_sub_id":"101","register_pk":"196077","name":"伊藤屋旅館門柱及び石垣","kana":"いとうやりょかんもんちゅうおよびいしがき","category":"産業3次","subcategory":"その他工作物","type_guess":"塀・門","type_guess_confidence":"high","period":"昭和前","pref":"神奈川県","address":"神奈川県足柄下郡湯河原町宮上字橋下484-1他","lat":35.14634606,"lng":139.07397129,"geo_status":"db","era":"昭和初期／平成20頃移築","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和初期","structure":"門柱 石造 石垣 石造、総延長47m","structure_material":"門柱 石造 石垣 石造","registered":"2014.04.25(平成26.04.25)","register_no":"14 － 0187","desc":"敷地南面の入口中央東寄りに門柱一対を立て、左右に石垣をのばす。門柱は花崗岩製で瘤出し仕上げに丸面取を施す。石垣は見付を方形とした切石を高さ一～二メートルに布積し、頂部に蒲鉾形の笠石を伏せる。積石も丸面を取り、重厚ながら柔和な印象をつくる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009930"},{"id":"00002526","register_sub_id":"101","register_pk":"103516","name":"岩本楼ローマ風呂","kana":"いわもとろうろーまぶろ","category":"産業3次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"神奈川県","address":"神奈川県藤沢市江の島2-2-7","lat":35.30108333,"lng":139.48025,"geo_status":"db","era":"昭和5頃","year":1930,"year_source":"db","year_min":1930,"year_max":1930,"year_label":null,"structure":"木造平屋建、ガラス屋根、建築面積43㎡","structure_material":"木造平屋建","registered":"2001.11.20(平成13.11.20)","register_no":"14 － 0058","desc":"江の島の老舗旅館の洋風浴室。浴室は方３間規模で，ガラスドームを架ける他，壁面には壁泉やベネチア窓風飾りをタイルやテラコッタで造り，脱衣室境には孔雀模様のステインドグラスを嵌める。タイル等は小森忍，ステインドグラスは別府七郎の製作と伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002526"},{"id":"00007986","register_sub_id":"101","register_pk":"128818","name":"上野屋玄関棟","kana":"うえのやげんかんとう","category":"産業3次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"神奈川県","address":"神奈川県足柄下郡湯河原町宮上字丸山616-1他","lat":35.14763818,"lng":139.07117875,"geo_status":"db","era":"昭和11頃／昭和25頃・昭和35頃・昭和50頃改修","year":1936,"year_source":"db","year_min":1936,"year_max":1936,"year_label":null,"structure":"木造2階建、鉄板一部銅板葺、建築面積385㎡","structure_material":"木造2階建","registered":"2010.01.15(平成22.01.15)","register_no":"14-0162","desc":"敷地の東南隅、東面して建つ。大広間部と玄関部がＬ字型に取り付く木造２階建、建築面積３８５㎡。屋根は入母屋造、鉄板及び銅板葺で、さらに前後に落棟を付け、正面中央には起りのある屋根の玄関を張り出す。複雑な外観構成が老舗旅館の風格を醸成する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007986"},{"id":"00007987","register_sub_id":"101","register_pk":"128819","name":"上野屋別館","kana":"うえのやべっかん","category":"産業3次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"大正","pref":"神奈川県","address":"神奈川県足柄下郡湯河原町宮上字丸山616-1他","lat":35.14775578,"lng":139.07106114,"geo_status":"db","era":"大正12／昭和25頃・昭和35頃・平成元頃改修","year":1923,"year_source":"db","year_min":1923,"year_max":1923,"year_label":null,"structure":"木造2階建、鉄板葺、建築面積195㎡","structure_material":"木造2階建","registered":"2010.01.15(平成22.01.15)","register_no":"14-0163","desc":"玄関棟の西面に接続する。木造２階建、鉄板葺で、建築面積１９５㎡。南北棟で、北入母屋造南寄棟造の南面に入母屋造の落棟を付設する。北半部は下見板張で、小壁を漆喰仕上げとし、銅板葺庇を付ける。本館や玄関棟と近接して建ち、変化のある佇まいを見せる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007987"},{"id":"00007985","register_sub_id":"101","register_pk":"128817","name":"上野屋本館","kana":"うえのやほんかん","category":"産業3次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"神奈川県","address":"神奈川県足柄下郡湯河原町宮上字丸山616-1他","lat":35.14757263,"lng":139.07099945,"geo_status":"db","era":"昭和5／昭和前期・昭和25増築・平成2・平成4改修","year":1930,"year_source":"db","year_min":1930,"year_max":1930,"year_label":null,"structure":"木造4階建、鋼板葺、建築面積195㎡、離れ付","structure_material":"木造4階建","registered":"2010.01.15(平成22.01.15)","register_no":"14-0161","desc":"山裾に占める敷地の南西に建つ。傾斜地に建つ木造４階建で、上階ほど階段状に山側へ張り出し、４階から階段により離れに至る。北面に入母屋破風を見せ、南面を切妻造とする鉄板葺。３、４階の正側面には銅板葺の庇と高欄をまわし、楼閣風の外観に造る。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007985"},{"id":"00011661","register_sub_id":"101","register_pk":"210677","name":"宇山商事店舗兼主屋","kana":"うやましょうじてんぽけんしゅおく","category":"産業3次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"昭和前","pref":"神奈川県","address":"神奈川県秦野市寿町2202","lat":35.375916,"lng":139.229014,"geo_status":"db","era":"昭和3年／昭和40年頃改修","year":1928,"year_source":"db","year_min":1928,"year_max":1928,"year_label":null,"structure":"木造2階建、瓦葺、建築面積79㎡","structure_material":"木造2階建","registered":"2017.06.28(平成29.06.28)","register_no":"14-0233","desc":"旧矢倉沢往還沿いに東面して建つ。一階下屋は一段、二階は二段の出桁造で、奥行きの深い下屋庇を構成する。内部は前土間とし、地域の町家の特徴を示す。壁を磨き漆喰にするなど丁寧な仕上げや、良材を用いた座敷部が、当地の歴史的景観を伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011661"},{"id":"00014340","register_sub_id":"101","register_pk":"511329","name":"小田原宿なりわい交流館（旧角吉店舗）","kana":"おだわらじゅくなりわいこうりゅうかん（きゅうかどきちてんぽ）","category":"産業3次","subcategory":"建築物","type_guess":"店舗","type_guess_confidence":"high","period":"昭和前","pref":"神奈川県","address":"神奈川県小田原市本町三丁目242","lat":35.2483,"lng":139.16,"geo_status":"db","era":"昭和7年／平成13年改修","year":1932,"year_source":"db","year_min":1932,"year_max":1932,"year_label":null,"structure":"木造2階建、瓦葺一部銅板葺、建築面積73㎡","structure_material":"木造2階建","registered":"2022.10.31(令和4.10.31)","register_no":"14 - 0318","desc":"小田原宿中心部にある漁網店の店舗。かつては魚市場が隣接。二階建、切妻造桟瓦葺、外壁下見板張、正面ガラス戸の下屋を設け、二階正面は出格子とし、二段の出桁造とする。一階は土間と１５畳のミセ、二階は漁具の作業場とした。水産業の歴史的景観を伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014340"},{"id":"00003954","register_sub_id":"101","register_pk":"104944","name":"金澤園","kana":"かなざわえん","category":"産業3次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"神奈川県","address":"神奈川県横浜市金沢区柴町46","lat":35.34404521,"lng":139.63526916,"geo_status":"db","era":"昭和4","year":1929,"year_source":"db","year_min":1929,"year_max":1929,"year_label":null,"structure":"木造2階建、瓦葺、建築面積252㎡","structure_material":"木造2階建","registered":"2004.03.02(平成16.03.02)","register_no":"14 － 0082","desc":"海岸の近傍に建てられた割烹旅館。入母屋造，桟瓦葺の木造２階建で，北面に玄関を設け，１，２階に４室ずつ客室を配す。客室は銘木を用いた凝ったつくりの座敷飾りや建具，欄間により，それぞれ趣向を凝らす。戦前の郊外行楽地における休泊施設の好例を示す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003954"},{"id":"00002228","register_sub_id":"101","register_pk":"103218","name":"環翠楼別館","kana":"かんすいろうべっかん","category":"産業3次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"大正","pref":"神奈川県","address":"神奈川県足柄下郡箱根町塔之澤88","lat":35.232662,"lng":139.093048,"geo_status":"db","era":"大正期","year":1919,"year_source":"estimated","year_min":1912,"year_max":1926,"year_label":"大正期","structure":"木造3階建、鉄板葺、建築面積396㎡","structure_material":"木造3階建","registered":"2001.08.28(平成13.08.28)","register_no":"14 － 0056","desc":"本館南棟の西側に位置し，国道１号線の屈曲に応じて本館とは棟の方向を振って建つ。入母屋造，鉄板葺の木造３階建で，２，３階は本館の３，４階とそれぞれ同レベルにあり，廊下で結ばれる。県下の真鶴に所在したものを移築したと伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002228"},{"id":"00002226","register_sub_id":"101","register_pk":"103216","name":"環翠楼本館北棟","kana":"かんすいろうほんかんきたとう","category":"産業3次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"大正","pref":"神奈川県","address":"神奈川県足柄下郡箱根町塔之澤88","lat":35.232986,"lng":139.093399,"geo_status":"db","era":"大正8","year":1919,"year_source":"db","year_min":1919,"year_max":1919,"year_label":null,"structure":"木造一部鉄筋コンクリート造4階建、鉄板葺、建築面積337㎡","structure_material":"木造一部鉄筋コンクリート造4階建","registered":"2001.08.28(平成13.08.28)","register_no":"14 － 0054","desc":"塔之澤で最も古い歴史をもつ旅館で，国道１号線と早川と湯坂山に囲まれた三角形状の敷地の北側，玉の緒橋西詰南に建つ。国道側からは３階建地下１階で，３階に７２畳敷の大広間を設ける。国道の曲がり縁に建つことから塔之澤のランドマークとなっている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002226"},{"id":"00002227","register_sub_id":"101","register_pk":"103217","name":"環翠楼本館南棟","kana":"かんすいろうほんかんみなみとう","category":"産業3次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"大正","pref":"神奈川県","address":"神奈川県足柄下郡箱根町塔之澤88","lat":35.232746,"lng":139.093307,"geo_status":"db","era":"大正13","year":1924,"year_source":"db","year_min":1924,"year_max":1924,"year_label":null,"structure":"木造4階建、鉄板瓦棒葺、建築面積545㎡","structure_material":"木造4階建","registered":"2001.08.28(平成13.08.28)","register_no":"14 － 0055","desc":"本館北棟の南方，湯坂山際に建つ。木造４階建で，平面形状はおおむねＬ型とし，最上階に１００畳大の「神代閣」と６０畳大の「万象閣」の大広間を配する。屋根は銅板瓦棒葺，千鳥破風付きの賑やかな入母屋造を洋風トラスで組む。棟梁は北棟と同じ井上米吉。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002227"},{"id":"00009740","register_sub_id":"101","register_pk":"195569","name":"桔梗屋主屋","kana":"ききょうやしゅおく","category":"産業3次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"神奈川県","address":"神奈川県藤沢市藤沢1-751-1他","lat":35.34696822,"lng":139.48535755,"geo_status":"db","era":"明治44頃／昭和初期増築","year":1911,"year_source":"db","year_min":1911,"year_max":1911,"year_label":null,"structure":"木造2階建、鉄板葺、建築面積115㎡","structure_material":"木造2階建","registered":"2013.12.24(平成25.12.24)","register_no":"14 － 0180","desc":"店蔵の北方に接続して建つ。一階は三室を配し、西側へ震災後増築、昭和初期に二階一部を増築した。一階三室は南からゲンカン、ブツマ、オクノザシキとする。オクノザシキは、トコ・違棚・平書院を備えた格の高い座敷で、当主の居室らしい落着いた空間としている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009740"},{"id":"00009741","register_sub_id":"101","register_pk":"195570","name":"桔梗屋文庫蔵","kana":"ききょうやぶんこぐら","category":"産業3次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"江戸","pref":"神奈川県","address":"神奈川県藤沢市藤沢1-752-1他","lat":35.34699915,"lng":139.48520407,"geo_status":"db","era":"文久元／大正14改修","year":1861,"year_source":"db","year_min":1861,"year_max":1861,"year_label":null,"structure":"土蔵造3階建、瓦葺、建築面積50㎡","structure_material":"土蔵造3階建","registered":"2013.12.24(平成25.12.24)","register_no":"14 － 0181","desc":"敷地西方に南北棟で建つ三階建の土蔵で、外壁の腰を海鼠壁とする。一階東面に二箇所の出入口を開き、二階南妻と東面に窓を設ける。小屋は登り梁で、中央間のみ和小屋とする。藤沢宿の中では登り梁を残す唯一の土蔵であるとともに、近世に遡る希少な遺例である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009741"},{"id":"00009739","register_sub_id":"101","register_pk":"195568","name":"桔梗屋店蔵","kana":"ききょうやみせぐら","category":"産業3次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"明治","pref":"神奈川県","address":"神奈川県藤沢市藤沢1-751-1他","lat":35.34688611,"lng":139.48530278,"geo_status":"db","era":"明治44","year":1911,"year_source":"db","year_min":1911,"year_max":1911,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積59㎡","structure_material":"土蔵造2階建","registered":"2013.12.24(平成25.12.24)","register_no":"14 － 0179","desc":"街道に南面して建つ土蔵造二階建で、外壁を黒漆喰塗とする。二階正面窓の掛子塗の窓枠や軒蛇腹などを丁寧につくり、一階主屋境には千人扉と呼ぶ重厚な観音開の土戸を吊るなど、優秀な左官技術を伝える。藤沢宿において関東大震災以前に遡る貴重な店舗建築。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009739"},{"id":"00011896","register_sub_id":"101","register_pk":"211061","name":"旧石曽根商店店舗兼主屋","kana":"きゅういしそねしょうてんてんぽけんしゅおく","category":"産業3次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"大正","pref":"神奈川県","address":"神奈川県藤沢市藤沢字東横須賀711","lat":35.346392,"lng":139.485747,"geo_status":"db","era":"大正13年／昭和42年改修","year":1924,"year_source":"db","year_min":1924,"year_max":1924,"year_label":null,"structure":"木造2階建、鉄板葺、建築面積115㎡","structure_material":"木造2階建","registered":"2017.10.27(平成29.10.27)","register_no":"14 - 0235","desc":"旧東海道藤沢宿に位置する履物屋の店舗兼主屋。木造二階建鉄板葺で、二階は出桁造とする。街路側にミセ、オロシバを配し、その奥に中廊下を通して六畳、四畳半、仏間を配し、その背後に台所等水廻りを突出させる。近代の藤沢宿の賑わいを今に伝える建物。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011896"},{"id":"00010566","register_sub_id":"101","register_pk":"201140","name":"旧稲元屋呉服店一番蔵","kana":"きゅういなもとやごふくてんいちばんぐら","category":"産業3次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"明治","pref":"神奈川県","address":"神奈川県藤沢市藤沢字東横須賀727","lat":35.34679444,"lng":139.4843,"geo_status":"db","era":"明治中期","year":1890,"year_source":"estimated","year_min":1883,"year_max":1897,"year_label":"明治中期","structure":"土蔵造2階建、鉄板葺、建築面積20㎡","structure_material":"土蔵造2階建","registered":"2015.08.04(平成27.08.04)","register_no":"14－0195","desc":"内蔵の南に東面して並び建つ。桁行三間梁間二間、土蔵造二階建、切妻造鉄板葺。外壁漆喰塗で鉢巻を廻らし、腰を鼠色とする。内部には関東大震災後に多数の筋違や金物が付加されて震災復旧の様子を窺うことができ、また藤沢宿の土蔵の古例としても価値がある。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010566"},{"id":"00010565","register_sub_id":"101","register_pk":"201139","name":"旧稲元屋呉服店内蔵","kana":"きゅういなもとやごふくてんうちぐら","category":"産業3次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"昭和前","pref":"神奈川県","address":"神奈川県藤沢市藤沢字東横須賀727","lat":35.34684167,"lng":139.48432222,"geo_status":"db","era":"昭和10年","year":1935,"year_source":"db","year_min":1935,"year_max":1935,"year_label":null,"structure":"土蔵造2階建、銅板葺、建築面積37㎡","structure_material":"土蔵造2階建","registered":"2015.08.04(平成27.08.04)","register_no":"14－0194","desc":"東海道藤沢宿で呉服商を営んだ稲元屋の土蔵。東面する桁行三間半梁間二間、切妻造銅板葺で蔵前を付ける。外壁を人造石洗出し及び研出し仕上げとして石造風に目地を切り、妻面の窓は扉廻りや庇を黒漆喰塗として立面を引き締める。宿場の面影を伝える土蔵。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010565"},{"id":"00011486","register_sub_id":"101","register_pk":"210452","name":"旧越前屋雨谷商店店舗兼主屋","kana":"きゅうえちぜんやあまやしょうてんてんぽけんしゅおく","category":"産業3次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"大正","pref":"神奈川県","address":"神奈川県藤沢市打戻1119","lat":35.387075,"lng":139.41258611,"geo_status":"db","era":"大正13年／昭和13年・平成26年移築","year":1924,"year_source":"db","year_min":1924,"year_max":1924,"year_label":null,"structure":"木造平屋建、鋼板葺、建築面積138㎡","structure_material":"木造平屋建","registered":"2017.05.02(平成29.05.02)","register_no":"14-0227","desc":"もと薬問屋の店舗兼用住宅。旧店舗部は角地に面したため、土間とガラス戸を矩の手に廻らし、帳場を設ける。出桁や庇の太い桁など、震災復興期らしい重厚さを見せる。旧主屋部は八畳二室の良質な座敷である。藤沢の往時の有様を今に伝えている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011486"},{"id":"00014767","register_sub_id":"101","register_pk":"519025","name":"旧澤良商店店舗兼主屋","kana":"きゅうさわりょうしょうてんてんぽけんおもや","category":"産業3次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"大正","pref":"神奈川県","address":"神奈川県秦野市本町三丁目2838","lat":35.370975,"lng":139.23054167,"geo_status":"db","era":"大正15年","year":1926,"year_source":"db","year_min":1926,"year_max":1926,"year_label":null,"structure":"木造2階建、銅板葺、建築面積114㎡","structure_material":"木造2階建","registered":"2024.03.06(令和6.03.06)","register_no":"14 - 0335","desc":"龍門寺参道入口に建つ元乾物青果商の店舗兼主屋。通りに西面する木造二階建切妻造平入銅板葺の店舗で、背面に平屋建寄棟造鉄板葺の主屋を接続。店舗一階は全体を土間床、北西に事務所を附属。二階は主座敷八畳と次の間を配す。秦野の賑わいを伝える商家遺構。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014767"},{"id":"00014768","register_sub_id":"101","register_pk":"519026","name":"旧澤良商店土蔵","kana":"きゅうさわりょうしょうてんどぞう","category":"産業3次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"high","period":"明治","pref":"神奈川県","address":"神奈川県秦野市本町三丁目2838","lat":35.371,"lng":139.23046667,"geo_status":"db","era":"明治前期／明治中期移築、大正後期改修","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治前期","structure":"木造2階建、鉄板葺、建築面積23㎡","structure_material":"木造2階建","registered":"2024.03.06(令和6.03.06)","register_no":"14 - 0336","desc":"店舗兼主屋の北に建つ旧商品蔵兼家財蔵。土蔵造二階建切妻造平入の置屋根で鉄板葺とし、片町通に妻を見せる。南面一箇所の戸口を店舗蔵前に開く。内部は一、二階とも一室で、窓は二階東妻のみとする。小屋組は登梁を牛梁で受ける。街路景観の要となる土蔵。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014768"},{"id":"00012136","register_sub_id":"101","register_pk":"352935","name":"旧鈴木薬店店舗兼主屋","kana":"きゅうすずきやくてんてんぽけんしゅおく","category":"産業3次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"昭和前","pref":"神奈川県","address":"神奈川県藤沢市大鋸二丁目270","lat":35.344699,"lng":139.487976,"geo_status":"db","era":"昭和10年","year":1935,"year_source":"db","year_min":1935,"year_max":1935,"year_label":null,"structure":"木造2階建、瓦葺、建築面積91㎡","structure_material":"木造2階建","registered":"2018.03.27(平成30.03.27)","register_no":"14-255","desc":"藤沢宿近くの境川東岸に位置する。二階建、切妻造桟瓦葺の商家で、二階天井高を二・九メートルと高く取り、八畳座敷と六畳次の間を並べ、硝子戸を用いて明るい空間を実現している。天井板、床廻りなども良材を用いた質の高いもので、近代商家の好例である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012136"},{"id":"00013058","register_sub_id":"101","register_pk":"368241","name":"旧田島屋材木店（古民家スタジオ・イシワタリ）主屋","kana":"きゅうたじまやざいもくてん（こみんかすたじおいしわたり）しゅおく","category":"産業3次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"昭和前","pref":"神奈川県","address":"神奈川県鎌倉市長谷一丁目269-3","lat":35.31396667,"lng":139.54185833,"geo_status":"db","era":"昭和2年／昭和30年代増築","year":1927,"year_source":"db","year_min":1927,"year_max":1927,"year_label":null,"structure":"木造2階建、瓦葺一部銅板葺、建築面積150㎡","structure_material":"木造2階建","registered":"2019.12.05(令和1.12.05)","register_no":"14 － 0274","desc":"通りの北側敷地に建つ二階建。一階南面に座敷二室を配して東側に玄関を構え、二階も南に二室を並べ、上下階とも南面の縁にガラス戸をたてる。材木商の建築らしく軸部堅牢で良材を多用する。変容著しい長谷周辺において昭和初期の様相を伝える希少な遺構。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013058"},{"id":"00013059","register_sub_id":"101","register_pk":"368242","name":"旧田島屋材木店（古民家スタジオ・イシワタリ）門及び塀","kana":"きゅうたじまやざいもくてん（こみんかすたじおいしわたり）もんおよびへい","category":"産業3次","subcategory":"その他工作物","type_guess":"塀・門","type_guess_confidence":"high","period":"昭和前","pref":"神奈川県","address":"神奈川県鎌倉市長谷一丁目269-3","lat":35.31389444,"lng":139.54190278,"geo_status":"db","era":"昭和2年","year":1927,"year_source":"db","year_min":1927,"year_max":1927,"year_label":null,"structure":"門 木造、間口1.8m 塀 木造、瓦葺、総延長17m","structure_material":"門 木造","registered":"2019.12.05(令和1.12.05)","register_no":"14 － 0275","desc":"敷地南辺東端に開く門と左右袖塀、敷地西辺まで折曲がりに延びる塀からなる。門は約二〇センチメートル角の門柱一対に板戸引違とし、袖塀は竪板張で笠木を載せる。塀は腰高のコンクリート基礎に竪板張の板塀をたてて銅板葺とする。瀟洒な屋敷構えを創る門塀。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013059"},{"id":"00004129","register_sub_id":"101","register_pk":"105119","name":"神戸屋ふるや店店舗及び主屋","kana":"こうべやふるやてんてんぽおよびしゅおく","category":"産業3次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"昭和前","pref":"神奈川県","address":"神奈川県小田原市国府津4-2-18","lat":35.2802942,"lng":139.21273025,"geo_status":"db","era":"昭和10頃","year":1935,"year_source":"db","year_min":1935,"year_max":1935,"year_label":null,"structure":"木造2階建、鉄板葺、建築面積73㎡","structure_material":"木造2階建","registered":"2004.06.09(平成16.06.09)","register_no":"14 － 0085","desc":"国府津駅前に位置し，国道１号線に面した角地に建つ。タクシー会社の車庫兼社屋として建てられたもので，現在では店舗として利用されている。木造であるが，外壁はモルタルで洋風石造建築を模しており，隅の円柱，窓周り，軒部等に特徴的な意匠を備えている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004129"},{"id":"00015422","register_sub_id":"101","register_pk":"533437","name":"幸保家住宅石蔵","kana":"こうぼけじゅうたくいしぐら","category":"産業3次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"大正","pref":"神奈川県","address":"神奈川県横須賀市東浦賀二丁目12-9","lat":35.24405556,"lng":139.72164167,"geo_status":"db","era":"大正4年","year":1915,"year_source":"db","year_min":1915,"year_max":1915,"year_label":null,"structure":"木骨石造2階建、瓦葺、建築面積17㎡","structure_material":"木骨石造2階建","registered":"2025.08.06(令和7.08.06)","register_no":"14 - 0363","desc":"主屋の南隣に建つ米蔵。切妻造桟瓦葺で鉢巻を含め、外壁全面に長尺の房州石を積上げた木骨石造建築。北面に戸口を設け、各階一室で木造軸組と束立の和小屋を現し、一階土間の内壁に荷擦木を打付ける。店舗兼主屋と一連で、浦賀の往事の景観を今に伝える石蔵。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00015422"},{"id":"00015421","register_sub_id":"101","register_pk":"533436","name":"幸保家住宅店舗兼主屋","kana":"こうぼけじゅうたくてんぽけんおもや","category":"産業3次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"大正","pref":"神奈川県","address":"神奈川県横須賀市東浦賀二丁目12-9","lat":35.24411667,"lng":139.72165278,"geo_status":"db","era":"大正14年／令和6年改修","year":1925,"year_source":"db","year_min":1925,"year_max":1925,"year_label":null,"structure":"木造2階建、瓦葺、建築面積42㎡","structure_material":"木造2階建","registered":"2025.08.06(令和7.08.06)","register_no":"14 - 0362","desc":"浦賀湾東側の街路に西面して建つ、元米穀商の店舗兼主屋。二階建寄棟造桟瓦葺で正面に下屋を付す。一階内部は前土間で、繊細な格子戸を建て、奥に二室を配す。二階は二室で表側を１０畳の床構え付き座敷とする。窓に手摺を付し港町の風情を伝える貴重な町家。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00015421"},{"id":"00002896","register_sub_id":"101","register_pk":"103886","name":"済生堂薬局小西本店店舗","kana":"さいせいどうやっきょくこにしほんてんてんぽ","category":"産業3次","subcategory":"建築物","type_guess":"店舗","type_guess_confidence":"high","period":"大正","pref":"神奈川県","address":"神奈川県小田原市本町4-2-48","lat":35.24711826,"lng":139.15691081,"geo_status":"db","era":"大正14頃","year":1925,"year_source":"db","year_min":1925,"year_max":1925,"year_label":null,"structure":"木造平屋建、瓦一部銅板葺、建築面積99㎡","structure_material":"木造平屋建","registered":"2002.08.21(平成14.08.21)","register_no":"14 － 0070","desc":"東海道に面して建つ店舗建築。木造・平屋建，寄棟造，桟瓦葺，平入で，正面に銅板瓦棒葺の下屋庇をつける。柱など主要部に欅材を用い，店部分は天井も高く，薬棚等の室内意匠もよく残る。市街化の進む旧中宿町にあり，かつての城下町の景観を今に伝えている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002896"},{"id":"00002140","register_sub_id":"101","register_pk":"103130","name":"ジェラール水屋敷地下貯水槽","kana":"じぇらーるみずやしきちかちょすいそう","category":"産業3次","subcategory":"その他工作物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"神奈川県","address":"神奈川県横浜市中区元町1-77","lat":35.43969934,"lng":139.65093928,"geo_status":"db","era":"明治10代","year":1877,"year_source":"converted","year_min":1877,"year_max":1877,"year_label":null,"structure":"煉瓦造、面積114㎡","structure_material":"煉瓦造","registered":"2001.04.24(平成13.04.24)","register_no":"14 － 0049","desc":"幕末から横浜に居留したフランス人ジェラールが経営した船舶給水業の施設で，兼営したフランス瓦煉瓦製造工場の地下に築造され，谷戸の湧水を集めて貯水した。天井はいわゆる防火床。水屋敷の遺構として親しまれ，最近ポケットパーク的に整備された。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002140"},{"id":"00005713","register_sub_id":"101","register_pk":"106701","name":"寸松堂蔵","kana":"すんしょうどうくら","category":"産業3次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"昭和前","pref":"神奈川県","address":"神奈川県鎌倉市笹目町292-1他","lat":35.31422899,"lng":139.54363998,"geo_status":"db","era":"昭和11","year":1936,"year_source":"db","year_min":1936,"year_max":1936,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積22㎡","structure_material":"土蔵造2階建","registered":"2006.10.18(平成18.10.18)","register_no":"14 － 0128","desc":"主屋北東隅に接続して道路に面して建つ。土蔵造２階建，切妻造，桟瓦葺。南北に開く窓は額縁を塗籠で張り出し，同じく塗籠の庇を設けるなど重厚である。内部に階段を設けず，主屋の１階，２階から各々の階に連絡する。主屋と一体となった土蔵形式を示す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005713"},{"id":"00005712","register_sub_id":"101","register_pk":"106700","name":"寸松堂主屋","kana":"すんしょうどうしゅおく","category":"産業3次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"昭和前","pref":"神奈川県","address":"神奈川県鎌倉市笹目町292-1他","lat":35.314121,"lng":139.543777,"geo_status":"db","era":"昭和11","year":1936,"year_source":"db","year_min":1936,"year_max":1936,"year_label":null,"structure":"木造2階建、銅板葺、建築面積232㎡、塔屋付","structure_material":"木造2階建","registered":"2006.10.18(平成18.10.18)","register_no":"14 － 0127","desc":"交差点の角地に建つ。木造２階建（塔屋付），入母屋造，瓦棒銅板葺。長押や組物を外部に見せて寺院建築風とし，塔屋には相輪を戴く。また外壁を塗籠として格子を設け，城郭風の意匠も混用する。店内部は格天井張。堅牢で特異な外観を呈する商店建築。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005712"},{"id":"00010944","register_sub_id":"101","register_pk":"208915","name":"関次商店穀物蔵","kana":"せきじしょうてんこくもつぐら","category":"産業3次","subcategory":"建築物","type_guess":"店舗","type_guess_confidence":"high","period":"明治","pref":"神奈川県","address":"神奈川県藤沢市本町四丁目1429","lat":35.34750556,"lng":139.48147222,"geo_status":"db","era":"明治19／大正後期増築","year":1886,"year_source":"db","year_min":1886,"year_max":1886,"year_label":null,"structure":"土蔵造平屋建、鉄板葺、建築面積91㎡","structure_material":"土蔵造平屋建","registered":"2016.02.25(平成28.02.25)","register_no":"14-0217","desc":"旧東海道に北面する敷地の南端に位置する。桁行九・一メートル梁間五・五メートルの建ちの高い平屋建土蔵で、和小屋を架ける。内部は半割丸太を各柱間に横方向に入れ込んで荷摺木にするという、独特な工法を使い、大壁を裏返ししない技法も特異である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010944"},{"id":"00010945","register_sub_id":"101","register_pk":"208916","name":"関次商店肥料蔵","kana":"せきじしょうてんひりょうぐら","category":"産業3次","subcategory":"建築物","type_guess":"店舗","type_guess_confidence":"high","period":"明治","pref":"神奈川県","address":"神奈川県藤沢市本町四丁目1429","lat":35.34750556,"lng":139.48147222,"geo_status":"db","era":"明治40／大正後期増築","year":1907,"year_source":"db","year_min":1907,"year_max":1907,"year_label":null,"structure":"木骨石造平屋建、瓦葺、建築面積50㎡","structure_material":"木骨石造平屋建","registered":"2016.02.25(平成28.02.25)","register_no":"14-0218","desc":"旧東海道に北面する敷地に建つ。木材で軸を組み、外壁に鎌倉石を張る混構造となる。内部の荷摺木の技法は穀物蔵と同様に半割丸太を各柱間に横方向に入れ込んで荷摺木とする。また関東大震災後、背面側にオロシと呼ぶ下屋を設ける。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010945"},{"id":"00014769","register_sub_id":"101","register_pk":"519027","name":"立花屋茶舗店舗兼主屋","kana":"たちばなやちゃほてんぽけんおもや","category":"産業3次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"江戸","pref":"神奈川県","address":"神奈川県秦野市本町三丁目2839","lat":35.37113333,"lng":139.23033889,"geo_status":"db","era":"慶応元年(1865)頃／明治後期改修、昭和2年移築、同10年・同45年頃増築","year":1865,"year_source":"db","year_min":1865,"year_max":1865,"year_label":null,"structure":"木造2階建、鉄板葺、建築面積147㎡","structure_material":"木造2階建","registered":"2024.03.06(令和6.03.06)","register_no":"14 - 0337","desc":"台町交差点北に位置する茶商の店舗兼主屋。つし二階建切妻造平入鉄板葺の店舗北に寄棟造二階建の主屋を接続。店舗は銅板葺下屋にガラス戸を建込む。主屋二階には東久邇宮宿所とした座敷を配す。通りに面した軒の低い町家が、秦野の歴史的な景観を形成する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014769"},{"id":"00014770","register_sub_id":"101","register_pk":"519028","name":"立花屋茶舗左の蔵","kana":"たちばなやちゃほひだりのくら","category":"産業3次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"high","period":"江戸","pref":"神奈川県","address":"神奈川県秦野市本町三丁目2839","lat":35.37114722,"lng":139.2305,"geo_status":"db","era":"江戸末期","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"木造2階建、鉄板葺、建築面積50㎡","structure_material":"木造2階建","registered":"2024.03.06(令和6.03.06)","register_no":"14 - 0338","desc":"店舗の東背後に建つ商品蔵兼家財蔵。土蔵造二階建の東西棟で、切妻造の置屋根を鉄板葺とし、西妻下屋に戸口を設け、両開の掛子塗戸を吊る。外壁は白漆喰塗で腰は下見板張。二階床に格子付の荷上口を備える。右の蔵と一体で龍門寺参道の景観をつくる土蔵。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014770"},{"id":"00014771","register_sub_id":"101","register_pk":"519029","name":"立花屋茶舗右の蔵","kana":"たちばなやちゃほみぎのくら","category":"産業3次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"high","period":"明治","pref":"神奈川県","address":"神奈川県秦野市本町三丁目2839","lat":35.37109722,"lng":139.23053611,"geo_status":"db","era":"明治41年／大正後期改修","year":1908,"year_source":"db","year_min":1908,"year_max":1908,"year_label":null,"structure":"木造2階建、鉄板葺、建築面積50㎡","structure_material":"木造2階建","registered":"2024.03.06(令和6.03.06)","register_no":"14 - 0339","desc":"店舗兼主屋の背後、左の蔵の南に並ぶ商品蔵兼家財蔵。土蔵造二階建切妻造妻入の置屋根鉄板葺とし左の蔵と一連で下屋を付す。外壁はモルタル塗で腰は洗出仕上。戸口は両開掛子塗戸。二階床に格子付荷上口を備える。左の蔵とともに龍門寺参道の景観をつくる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014771"},{"id":"00013239","register_sub_id":"101","register_pk":"366228","name":"玉屋本店店舗兼主屋","kana":"たまやほんてんてんぽけんおもや","category":"産業3次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"昭和前","pref":"神奈川県","address":"神奈川県藤沢市片瀬海岸一丁目2617-1","lat":35.31025278,"lng":139.48666944,"geo_status":"db","era":"昭和10年","year":1935,"year_source":"db","year_min":1935,"year_max":1935,"year_label":null,"structure":"木造2階建、銅板葺一部金属板葺、建築面積183㎡","structure_material":"木造2階建","registered":"2020.04.03(令和2.04.03)","register_no":"14 － 0280","desc":"江ノ島参詣道沿いの老舗羊羹店。二階建町家の一階正面を下屋、上下階とも出桁造とする。前寄りの土間のミセは大断面のケヤキで重厚な軸部としつつ、屋号を表すステンドグラスを飾り瀟洒な意匠も備える。後方はコウバ等を配する。戦前の参詣道の様相を伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013239"},{"id":"00002895","register_sub_id":"101","register_pk":"103885","name":"だるま料理店主屋","kana":"だるまりょうりてんしゅおく","category":"産業3次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"大正","pref":"神奈川県","address":"神奈川県小田原市本町2-1-30","lat":35.25132758,"lng":139.15952486,"geo_status":"db","era":"大正15","year":1926,"year_source":"db","year_min":1926,"year_max":1926,"year_label":null,"structure":"木造2階建、銅板一部瓦葺、建築面積503㎡","structure_material":"木造2階建","registered":"2002.08.21(平成14.08.21)","register_no":"14 － 0069","desc":"明治２６年に地元の網元が創業した老舗で，現在の主屋は関東大震災後に，桧・松・欅の良材を集め，随所に和風の粋を凝らして建てた質の高い建築。木造・２階建で，正面中央に唐破風玄関を設け，比翼入母屋造風屋根とするなど，楼閣風の際だった存在である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002895"},{"id":"00007462","register_sub_id":"101","register_pk":"108444","name":"茅ヶ崎館中二階棟","kana":"ちがさきかんちゅうにかいとう","category":"産業3次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"大正","pref":"神奈川県","address":"神奈川県茅ヶ崎市中海岸3-11595-1他","lat":35.32037,"lng":139.401077,"geo_status":"db","era":"大正14","year":1925,"year_source":"db","year_min":1925,"year_max":1925,"year_label":null,"structure":"木造平屋建、スレート葺、建築面積124㎡","structure_material":"木造平屋建","registered":"2009.01.08(平成21.01.08)","register_no":"14 － 0149","desc":"広間棟の南西に位置し、桁行１１ｍ梁間５．５ｍ規模の寄棟造南北棟と、直交する桁行８．２ｍ梁間７．１ｍの入母屋造東西棟よりなる。スレート葺で、各棟南面には下屋庇を付ける。床を高く張る小規模な棟を鉤の手に配して、変化に富む敷地景観をつくる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007462"},{"id":"00007461","register_sub_id":"101","register_pk":"108443","name":"茅ヶ崎館広間棟","kana":"ちがさきかんひろまとう","category":"産業3次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"大正","pref":"神奈川県","address":"神奈川県茅ヶ崎市中海岸3-11595-1他","lat":35.3205327,"lng":139.4012369,"geo_status":"db","era":"大正15頃","year":1926,"year_source":"db","year_min":1926,"year_max":1926,"year_label":null,"structure":"木造平屋一部2階建、鉄板葺・スレート葺及び瓦葺、建築面積274㎡","structure_material":"木造平屋一部2階建","registered":"2009.01.08(平成21.01.08)","register_no":"14 － 0148","desc":"茅ヶ崎海岸の高台に占める敷地の中央、南庭に面して建つ。東西に長い木造平屋建の寄棟造鉄板葺で、東側に入母屋造スレート葺の２階建を設ける。西端に開放的な広間を配し、簡素で軽快な意匠のトコや付書院を構える。南庭越しに湘南の海を望む旅館の主棟である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007461"},{"id":"00007734","register_sub_id":"101","register_pk":"108716","name":"塔之澤一の湯本館","kana":"とうのさわいちのゆほんかん","category":"産業3次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"神奈川県","address":"神奈川県足柄下郡箱根町塔之澤字湯ノ沢90-1他","lat":35.23329905,"lng":139.0934332,"geo_status":"db","era":"明治後期／大正6・大正11増築・昭和中期・昭和後期改修","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治後期","structure":"木造4階一部地下1階建、銅板葺及び鉄板葺、建築面積786㎡","structure_material":"木造4階一部地下1階建","registered":"2009.08.07(平成21.08.07)","register_no":"14-0155","desc":"塔之澤温泉の入口、玉の緒橋の袂に位置する。木造を主体とする４階地下１階建。屋根を銅板や鉄板で葺き、入母屋造や寄棟造などを階高に応じて組み合わせて、複雑な外観を造る。大広間や客室、浴室などに様々な意匠が見られ、老舗旅館の歴史を伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007734"},{"id":"00006021","register_sub_id":"101","register_pk":"107006","name":"箱根太陽山荘別館","kana":"はこねたいようさんそうべっかん","category":"産業3次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"大正","pref":"神奈川県","address":"神奈川県足柄下郡箱根町強羅1320-375","lat":35.25041129,"lng":139.04568183,"geo_status":"db","era":"大正後期／昭和28増改築","year":1922,"year_source":"estimated","year_min":1919,"year_max":1926,"year_label":"大正後期","structure":"木造2階一部3階建、瓦葺一部鉄板葺、建築面積168㎡","structure_material":"木造2階一部3階建","registered":"2006.11.29(平成18.11.29)","register_no":"14 － 0138","desc":"本館西に道路を挟んで建つ木造３階建。東下りの傾斜に従って床高に差があり，本館３階から別館２階への渡廊下を道路上に架ける。２階以上が客室で，３階に１０畳と６畳の続き間座敷を設ける。切妻造，桟瓦葺で，南面中央に入母屋屋根を突出して変化をつける。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006021"},{"id":"00005940","register_sub_id":"101","register_pk":"106925","name":"箱根太陽山荘本館","kana":"はこねたいようさんそうほんかん","category":"産業3次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"神奈川県","address":"神奈川県足柄下郡箱根町強羅1320-374","lat":35.250595,"lng":139.045883,"geo_status":"db","era":"昭和15／昭和25・26増改築","year":1940,"year_source":"db","year_min":1940,"year_max":1940,"year_label":null,"structure":"木造2階一部3階建、瓦葺、建築面積267㎡","structure_material":"木造2階一部3階建","registered":"2006.11.29(平成18.11.29)","register_no":"14 － 0137","desc":"警視庁の保険療養所として創建と伝え，東下りの傾斜地に建つ。西側道路に面した２階に入母屋屋根の玄関を設け，寄棟造，桟瓦葺の木造３階建とする。３階に８畳間を中心とする客室を配す。南面縁外の擬宝珠高欄が目をひく。湯治場の風情を残す近代和風建築。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005940"},{"id":"00004128","register_sub_id":"101","register_pk":"105118","name":"長谷川家住宅石蔵","kana":"はせがわけじゅうたくいしぐら","category":"産業3次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"大正","pref":"神奈川県","address":"神奈川県小田原市国府津3-2-25","lat":35.28003837,"lng":139.20981516,"geo_status":"db","era":"大正5","year":1916,"year_source":"db","year_min":1916,"year_max":1916,"year_label":null,"structure":"木骨石造2階建、瓦葺、建築面積41㎡","structure_material":"木骨石造2階建","registered":"2004.06.09(平成16.06.09)","register_no":"14 － 0084","desc":"国府津地区の東海道近傍に建つ木骨石造２階建の蔵。古写真より大正５年の建築であることが知られる。１階は西面に戸口２箇所を開き，内部は２室構成とする。屋根は切妻造，桟瓦葺で，関東大震災後に設けられた補強帯鉄が外観のアクセントとなっている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004128"},{"id":"00004127","register_sub_id":"101","register_pk":"105117","name":"長谷川家住宅店舗及び主屋","kana":"はせがわけじゅうたくてんぽおよびしゅおく","category":"産業3次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"昭和前","pref":"神奈川県","address":"神奈川県小田原市国府津3-13-4","lat":35.27956821,"lng":139.20983249,"geo_status":"db","era":"昭和2","year":1927,"year_source":"db","year_min":1927,"year_max":1927,"year_label":null,"structure":"木造2階建、瓦葺、建築面積157㎡","structure_material":"木造2階建","registered":"2004.06.09(平成16.06.09)","register_no":"14 － 0083","desc":"国府津地区の東海道沿いにあって，関東大震災後の復興期に建てられた店舗兼住居。木造２階建，平入，入母屋造，桟瓦葺で，棟木銘より昭和２年の上棟が知られる。正面軒は出桁造で支え，屋根には緩やかなむくりをつける。国府津における震災復興町家の好例。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004127"},{"id":"00008430","register_sub_id":"101","register_pk":"134826","name":"日影茶屋本店石蔵","kana":"ひかげちゃやほんてんいしくら","category":"産業3次","subcategory":"建築物","type_guess":"店舗","type_guess_confidence":"high","period":"大正","pref":"神奈川県","address":"神奈川県三浦郡葉山町堀内字五ツ合16-1","lat":35.28380056,"lng":139.56984488,"geo_status":"db","era":"大正10年頃","year":1921,"year_source":"db","year_min":1921,"year_max":1921,"year_label":null,"structure":"石造2階建、瓦葺、建築面積31㎡","structure_material":"石造2階建","registered":"2011.01.26(平成23.01.26)","register_no":"14 － 0170","desc":"客室棟の南方に位置する。石造二階建、東西棟の切妻造桟瓦葺で、桁行六・三メートル梁間四・五メートル。外壁は石目に特徴ある房州石とし、道路側の西妻の二階開口両側を半円柱の柱型とするなど凝ったつくりとなる。重厚で風合いある石蔵。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008430"},{"id":"00008429","register_sub_id":"101","register_pk":"134825","name":"日影茶屋本店客室棟","kana":"ひかげちゃやほんてんきゃくしつとう","category":"産業3次","subcategory":"建築物","type_guess":"店舗","type_guess_confidence":"high","period":"大正","pref":"神奈川県","address":"神奈川県三浦郡葉山町堀内字五ツ合16-1他","lat":35.28416703,"lng":139.56993077,"geo_status":"db","era":"大正12年／昭和9年・昭和40年頃改修","year":1923,"year_source":"db","year_min":1923,"year_max":1923,"year_label":null,"structure":"木造2階建、瓦葺、建築面積390㎡","structure_material":"木造2階建","registered":"2011.01.26(平成23.01.26)","register_no":"14 － 0169","desc":"通りに西面して車寄せを構える南北棟と、これに北側で直行する東西棟からなる。木造二階建、入母屋造桟瓦葺、建築面積三九〇平方メートル。南北棟は二階を広間とし、東西棟は各階とも小部屋に分ける。簓子下見板張に大きく開口を取り、老舗旅館の面影を示す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008429"},{"id":"00003209","register_sub_id":"101","register_pk":"104199","name":"福住旅館別荘石蔵","kana":"ふくずみりょかんべっそういしぐら","category":"産業3次","subcategory":"建築物","type_guess":"旅館","type_guess_confidence":"high","period":"明治","pref":"神奈川県","address":"神奈川県足柄下郡箱根町湯本字湯場613-1","lat":35.23106772,"lng":139.09902354,"geo_status":"db","era":"明治初期／昭和8移築","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治初期","structure":"木骨石造2階建、瓦葺、建築面積18㎡","structure_material":"木骨石造2階建","registered":"2003.03.18(平成15.03.18)","register_no":"14 － 0079","desc":"主屋北東端の東方に棟をやや振って建つ。桁行２間半梁間２間，桟瓦葺，切妻造の２階建妻入蔵で，福住旅館金泉楼及び萬翆楼と同様に外部には白石あるいは湯本石と呼ばれる地元産の凝灰岩を積む。箱根における数少ない木骨石造建築の遺存例として貴重である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003209"},{"id":"00003208","register_sub_id":"101","register_pk":"104198","name":"福住旅館別荘主屋","kana":"ふくずみりょかんべっそうしゅおく","category":"産業3次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"大正","pref":"神奈川県","address":"神奈川県足柄下郡箱根町湯本字湯場613-1","lat":35.230804,"lng":139.098862,"geo_status":"db","era":"大正7","year":1918,"year_source":"db","year_min":1918,"year_max":1918,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積292㎡","structure_material":"木造平屋建","registered":"2003.03.18(平成15.03.18)","register_no":"14 － 0078","desc":"湯坂山の山裾東縁に位置する。ほぼ南を正面としたコ字型平面をもつ，桟瓦葺，寄棟造の木造平屋建で，北側の１間幅廊下の南方に和室７室と台所，北方に便所と浴室を配する。湯本福住旅館の長期滞在者用客室として建設された別荘風の上質な数寄屋造建築。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003208"},{"id":"00003210","register_sub_id":"101","register_pk":"104200","name":"福住樓主屋","kana":"ふくずみろうしゅおく","category":"産業3次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"神奈川県","address":"神奈川県足柄下郡箱根町塔之澤74","lat":35.23281794,"lng":139.09455721,"geo_status":"db","era":"明治20頃-昭和初期","year":1887,"year_source":"db","year_min":1887,"year_max":1887,"year_label":null,"structure":"木造地上3階地下1階建、鉄板葺・スレート葺及び瓦葺、建築面積2133㎡","structure_material":"木造地上3階地下1階建","registered":"2003.03.18(平成15.03.18)","register_no":"14 － 0080","desc":"玉の緒橋から千歳橋にかけての早川左岸に建築的アンサンブルを奏でる。国道１号線沿の玄関棟とその奥の棟は前身の「玉之湯旅館」時代の木骨石造建築を改造したもの。西方に浴室棟や木造３階建の各室意匠を変えた客室棟，質の高い書院造の広間棟などを連ねる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003210"},{"id":"00003211","register_sub_id":"101","register_pk":"104201","name":"福住樓茶室","kana":"ふくずみろうちゃしつ","category":"産業3次","subcategory":"建築物","type_guess":"事務所","type_guess_confidence":"low","period":"昭和前","pref":"神奈川県","address":"神奈川県足柄下郡箱根町塔之澤74","lat":35.232544,"lng":139.093964,"geo_status":"db","era":"昭和8頃","year":1933,"year_source":"db","year_min":1933,"year_max":1933,"year_label":null,"structure":"木造平屋建、スレート葺、建築面積35㎡","structure_material":"木造平屋建","registered":"2003.03.18(平成15.03.18)","register_no":"14 － 0081","desc":"主屋広間棟の西方，早川寄りに独立して建つ。「洗小亭」と名付けられ，中央に位置する５畳間の北西方に小間，南西方に風呂場を配する。小間は中板付３畳台目の茶室で，福住樓の顧客のひとりであり，数寄者として知られる野崎幻庵の設計と伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003211"},{"id":"00010273","register_sub_id":"101","register_pk":"199046","name":"藤田屋旅館本館","kana":"ふじたやりょかんほんかん","category":"産業3次","subcategory":"建築物","type_guess":"旅館","type_guess_confidence":"high","period":"大正","pref":"神奈川県","address":"神奈川県足柄下郡湯河原町宮上字橋下495","lat":35.146747,"lng":139.073783,"geo_status":"db","era":"大正12年／昭和4年・昭和26年改修","year":1923,"year_source":"db","year_min":1923,"year_max":1923,"year_label":null,"structure":"木造2階建、瓦葺一部銅板葺、建築面積385㎡","structure_material":"木造2階建","registered":"2014.12.19(平成26.12.19)","register_no":"14-0191","desc":"木造二階建の東棟と西棟を雁行して建て、中央に入母屋造の玄関を構える。川に臨んで八畳主体の客室を並べて高欄を設え、室内のトコや欄間に繊細な意匠の組子細工や透彫を飾る。東棟では入口に多様な数寄屋意匠の小庇を付す。温泉街の旅情を醸す旅館建築。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010273"},{"id":"00000397","register_sub_id":"101","register_pk":"101387","name":"富士屋ホテルアイリー","kana":"ふじやほてるあいりー","category":"産業3次","subcategory":"建築物","type_guess":"ホテル","type_guess_confidence":"high","period":"明治","pref":"神奈川県","address":"神奈川県足柄下郡箱根町宮ノ下359","lat":35.24332907,"lng":139.05975701,"geo_status":"db","era":"明治17","year":1884,"year_source":"db","year_min":1884,"year_max":1884,"year_label":null,"structure":"木造2階建，鉄板葺，建築面積160㎡","structure_material":"木造2階建","registered":"1997.12.12(平成9.12.12)","register_no":"14 － 0013","desc":"敷地南方の斜面に北面して建つ。創業間もない時期の建物で，昭和10年に現在地に移築された。正面両端に突出部をつくり中央に唐破風屋根を設ける点は，本館，一・二号館と共通する。現存する数少ない我が国最初期のリゾートホテル施設として価値がある。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000397"},{"id":"00000395","register_sub_id":"101","register_pk":"101385","name":"富士屋ホテル１号館","kana":"ふじやほてるいちごうかん","category":"産業3次","subcategory":"建築物","type_guess":"ホテル","type_guess_confidence":"high","period":"明治","pref":"神奈川県","address":"神奈川県足柄下郡箱根町宮ノ下359","lat":35.24388275,"lng":139.0590483,"geo_status":"db","era":"明治39","year":1906,"year_source":"db","year_min":1906,"year_max":1906,"year_label":null,"structure":"木造2階建，瓦葺，建築面積292㎡","structure_material":"木造2階建","registered":"1997.12.12(平成9.12.12)","register_no":"14 － 0011","desc":"本館の南に客室用の新館として建てられた。左右対称で正面両端に八角平面の突出部を持ち中央に唐破風屋根の玄関ポーチを持つ特異な外観は本館に似る。屋根や玄関の意匠を簡略にし，和風の要素を押さえる点に特徴がある。カムフィ・ロッジの異名を持つ。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000395"},{"id":"00000399","register_sub_id":"101","register_pk":"101389","name":"富士屋ホテル食堂","kana":"ふじやほてるしょくどう","category":"産業3次","subcategory":"建築物","type_guess":"ホテル","type_guess_confidence":"high","period":"昭和前","pref":"神奈川県","address":"神奈川県足柄下郡箱根町宮ノ下359","lat":35.24449401,"lng":139.0591546,"geo_status":"db","era":"昭和5","year":1930,"year_source":"db","year_min":1930,"year_max":1930,"year_label":null,"structure":"鉄筋コンクリート造・木造2階建塔屋付，銅板葺一部鉄板葺，589㎡","structure_material":"鉄筋コンクリート造・木造2階建塔屋付","registered":"1997.12.12(平成9.12.12)","register_no":"14 － 0015","desc":"和風の意匠を基調にした建物で，１階を鉄筋コンクリート造，２階を木造とする。中央部に２重の塔屋「昇天閣」を設けた外観は特異で，要所に彫刻を配した書院風の豪華な室内意匠も優れている。設計には，木子幸三郎が係わった。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000399"},{"id":"00000396","register_sub_id":"101","register_pk":"101386","name":"富士屋ホテル２号館","kana":"ふじやほてるにごうかん","category":"産業3次","subcategory":"建築物","type_guess":"ホテル","type_guess_confidence":"high","period":"明治","pref":"神奈川県","address":"神奈川県足柄下郡箱根町宮ノ下359","lat":35.24375429,"lng":139.05925205,"geo_status":"db","era":"明治39","year":1906,"year_source":"db","year_min":1906,"year_max":1906,"year_label":null,"structure":"木造2階建，瓦葺，建築面積292㎡","structure_material":"木造2階建","registered":"1997.12.12(平成9.12.12)","register_no":"14 － 0012","desc":"一号館と同時期に建てられた同一の規模・意匠になる建物。レストフル・カテジの異名を持つ。鎧戸付きの縦長の上下窓，天井や軒に用いられた繰形状の蛇腹装飾に本格的な洋風の意匠をみることができ，用いられた技術・技能の水準の高さがうかがえる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000396"},{"id":"00000398","register_sub_id":"101","register_pk":"101388","name":"富士屋ホテル花御殿","kana":"ふじやほてるはなごてん","category":"産業3次","subcategory":"建築物","type_guess":"ホテル","type_guess_confidence":"high","period":"昭和前","pref":"神奈川県","address":"神奈川県足柄下郡箱根町宮ノ下359","lat":35.24371443,"lng":139.05962412,"geo_status":"db","era":"昭和11","year":1936,"year_source":"db","year_min":1936,"year_max":1936,"year_label":null,"structure":"鉄筋コンクリート造5階建，銅板葺一部鉄板葺，建築面積1088㎡","structure_material":"鉄筋コンクリート造5階建","registered":"1997.12.12(平成9.12.12)","register_no":"14 － 0014","desc":"コの字型平面を持つ鉄筋コンクリート造，５階建の建物。意匠は和風を基調とする。複雑な屋根や高欄付のバルコニー等に特徴がある特異な外観を持ち，豪華な室内意匠にもみるべきものがある。設計はホテルの経営者山口正造で，工事請負は河原徳次郎である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000398"},{"id":"00000394","register_sub_id":"101","register_pk":"101384","name":"富士屋ホテル本館","kana":"ふじやほてるほんかん","category":"産業3次","subcategory":"建築物","type_guess":"ホテル","type_guess_confidence":"high","period":"明治","pref":"神奈川県","address":"神奈川県足柄下郡箱根町宮ノ下359","lat":35.24418395,"lng":139.05901286,"geo_status":"db","era":"明治24","year":1891,"year_source":"db","year_min":1891,"year_max":1891,"year_label":null,"structure":"木造2階建，瓦葺，建築面積706㎡","structure_material":"木造2階建","registered":"1997.12.12(平成9.12.12)","register_no":"14 － 0010","desc":"外国人の宿泊を意識して，全体に洋風の意匠を基調にしながら内外の要所に和風の意匠を加味した特異な建物。正面中央に唐破風屋根の玄関ポーチ，左右に八角平面の突出部をつくり正面性を強調した左右対称の外観に特徴がある。工事請負は河原兵次郎。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000394"},{"id":"00013241","register_sub_id":"101","register_pk":"366230","name":"富士屋旅館旧三号館","kana":"ふじやりょかんきゅうさんごうかん","category":"産業3次","subcategory":"建築物","type_guess":"旅館","type_guess_confidence":"high","period":"大正","pref":"神奈川県","address":"神奈川県足柄下郡湯河原町宮上字橋上557-1","lat":35.14634722,"lng":139.07321667,"geo_status":"db","era":"大正12年頃","year":1923,"year_source":"db","year_min":1923,"year_max":1923,"year_label":null,"structure":"木造2階建、瓦葺、建築面積159㎡","structure_material":"木造2階建","registered":"2020.04.03(令和2.04.03)","register_no":"14 － 0282","desc":"湯河原温泉の川沿いに建つ二階建の木造旅館。入母屋造の主体部の両端から川側に入母屋の張出しを設け、大屋根の中央に千鳥破風を飾る。上下階とも窓上に庇を廻らし、上階は刎高欄付の縁を廻らすなど、風格ある立面を構成する。往時の温泉街の風情を伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013241"},{"id":"00014772","register_sub_id":"101","register_pk":"519030","name":"保全堂薬局店舗兼主屋","kana":"ほぜんどうやっきょくてんぽけんおもや","category":"産業3次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"昭和前","pref":"神奈川県","address":"神奈川県秦野市本町一丁目2626-1他","lat":35.37406667,"lng":139.22760278,"geo_status":"db","era":"昭和3年／昭和40年代改修","year":1928,"year_source":"db","year_min":1928,"year_max":1928,"year_label":null,"structure":"木造2階建、鉄板葺一部銅板葺、建築面積188㎡","structure_material":"木造2階建","registered":"2024.03.06(令和6.03.06)","register_no":"14 - 0340","desc":"秦野の本町四ツ角交差点の南に位置する薬局の店舗兼主屋。2階建洋風店舗の西に2階建和風主屋を接続する。店舗は正面中央を薄く張り出し三連の上下窓を開け、出隅の柱頭飾のレリーフなどセセッション風意匠を用いた外観が、通りの歴史的な景観を形成する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014772"},{"id":"00009440","register_sub_id":"101","register_pk":"194233","name":"松の茶屋田舎家","kana":"まつのちゃやいなかや","category":"産業3次","subcategory":"建築物","type_guess":"店舗","type_guess_confidence":"high","period":"大正","pref":"神奈川県","address":"神奈川県足柄下郡箱根町湯本字上町518-1他","lat":35.22854073,"lng":139.09872689,"geo_status":"db","era":"大正3年頃","year":1914,"year_source":"db","year_min":1914,"year_max":1914,"year_label":null,"structure":"木造平屋一部2階建、茅葺一部瓦葺、建築面積356㎡","structure_material":"木造平屋一部2階建","registered":"2013.03.29(平成25.03.29)","register_no":"14 － 0173","desc":"敷地の中ほどに建ち、木造平屋一部二階建、建築面積三五六平方メートルである。東半の入母屋造茅葺部分には残月の間や大炉の間を、西半の桟瓦葺部には霞の間などを配し、いずれも数寄屋風意匠を基調として多彩な室内空間を創る。瀟洒なつくりのもと別荘建築。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009440"},{"id":"00009443","register_sub_id":"101","register_pk":"194236","name":"松の茶屋松月","kana":"まつのちゃやしょうげつ","category":"産業3次","subcategory":"建築物","type_guess":"店舗","type_guess_confidence":"high","period":"昭和前","pref":"神奈川県","address":"神奈川県足柄下郡箱根町湯本字上町518-1他","lat":35.22827899,"lng":139.09830572,"geo_status":"db","era":"昭和前期／昭和34年移築・昭和後期改修","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和前期","structure":"木造平屋建、銅板葺、建築面積69㎡","structure_material":"木造平屋建","registered":"2013.03.29(平成25.03.29)","register_no":"14 － 0176","desc":"中央棟西側に渡廊下を介して接続する。木造平屋建、建築面積六九平方メートル、寄棟造、茅葺型銅板葺である。外壁は真壁漆喰塗りで、下部に丸竹を詰打ちとする。室内は西端に主室である松月の間を配し、東側に四畳半などを並べる。落着いた佇まいの離れ建築。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009443"},{"id":"00009441","register_sub_id":"101","register_pk":"194234","name":"松の茶屋中央棟","kana":"まつのちゃやちゅうおうとう","category":"産業3次","subcategory":"建築物","type_guess":"店舗","type_guess_confidence":"high","period":"昭和中","pref":"神奈川県","address":"神奈川県足柄下郡箱根町湯本字上町518-1他","lat":35.2284741,"lng":139.09857222,"geo_status":"db","era":"昭和27年／昭和後期改修","year":1952,"year_source":"db","year_min":1952,"year_max":1952,"year_label":null,"structure":"木造平屋一部2階建、こけら葺一部瓦葺、建築面積363㎡","structure_material":"木造平屋一部2階建","registered":"2013.03.29(平成25.03.29)","register_no":"14 － 0174","desc":"建物群の中央に建ち、木造平屋一部二階建、こけら葺一部桟瓦葺、建築面積三六三平方メートル。南面東寄りに玄関を構え、屈曲する廊下沿いに上質なつくりの客室や、調理場を配置する。複雑な平面と屋根構成になり、変化に富む外観をつくる、もと旅館の客室棟。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009441"},{"id":"00009442","register_sub_id":"101","register_pk":"194235","name":"松の茶屋浴室棟","kana":"まつのちゃやよくしつとう","category":"産業3次","subcategory":"建築物","type_guess":"店舗","type_guess_confidence":"high","period":"昭和中","pref":"神奈川県","address":"神奈川県足柄下郡箱根町湯本字上町518-1他","lat":35.22848124,"lng":139.09830572,"geo_status":"db","era":"昭和28年","year":1953,"year_source":"db","year_min":1953,"year_max":1953,"year_label":null,"structure":"木造平屋建、銅板葺、建築面積18㎡、渡廊下付","structure_material":"木造平屋建","registered":"2013.03.29(平成25.03.29)","register_no":"14 － 0175","desc":"中央棟北西部の北側に渡廊下を介して建ち、谷側を大きなガラス窓として対岸の山並みを望む浴室棟。木造平屋建、建築面積一八平方メートル、八注造銅板葺。平面は八角形で中央に石製の円形浴槽を備え、床と腰壁に大理石を張るなど独特な形式になる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009442"},{"id":"00005815","register_sub_id":"101","register_pk":"106802","name":"三河屋本店蔵","kana":"みかわやほんてんくら","category":"産業3次","subcategory":"建築物","type_guess":"店舗","type_guess_confidence":"high","period":"昭和前","pref":"神奈川県","address":"神奈川県鎌倉市雪ノ下1-270-1他","lat":35.32283115,"lng":139.55398771,"geo_status":"db","era":"昭和2","year":1927,"year_source":"db","year_min":1927,"year_max":1927,"year_label":null,"structure":"木造平屋建、鉄板葺、建築面積84㎡","structure_material":"木造平屋建","registered":"2006.10.18(平成18.10.18)","register_no":"14 － 0126","desc":"店舗兼住宅の北側後方に建つ。桁行８間，梁間３間の規模で，木造平屋建，切妻造，波形鉄板葺。内部を３室に間仕切り，中央の室には中２階を設ける。鎌倉市内に現存する蔵の中では比較的規模が大きく，近代の鎌倉が発展した時期の商家における遺構として重要。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005815"},{"id":"00005734","register_sub_id":"101","register_pk":"106722","name":"三河屋本店店舗兼住宅","kana":"みかわやほんてんてんぽけんじゅうたく","category":"産業3次","subcategory":"建築物","type_guess":"店舗","type_guess_confidence":"high","period":"昭和前","pref":"神奈川県","address":"神奈川県鎌倉市雪ノ下1-270-1他","lat":35.32269826,"lng":139.55408224,"geo_status":"db","era":"昭和2","year":1927,"year_source":"db","year_min":1927,"year_max":1927,"year_label":null,"structure":"木造2階建、瓦葺、建築面積210㎡","structure_material":"木造2階建","registered":"2006.10.18(平成18.10.18)","register_no":"14 － 0125","desc":"若宮大路に面して建つ。桁行５間，間口８間の規模で，木造２階建，切妻造，桟瓦葺。１階正面に下屋を張り出す。店舗は木太い根太天井を現し，通り土間を通し，床上部奥に座敷を配する。正面軒を出桁造りとし，正面に成の高い長大な差鴨居を渡し重厚な外観とする。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005734"},{"id":"00008832","register_sub_id":"101","register_pk":"162275","name":"三河屋旅館本館","kana":"みかわやりょかんほんかん","category":"産業3次","subcategory":"建築物","type_guess":"旅館","type_guess_confidence":"high","period":"大正","pref":"神奈川県","address":"神奈川県足柄下郡箱根町小涌谷字小涌谷503-1","lat":35.23702357,"lng":139.04653856,"geo_status":"db","era":"大正13年頃","year":1924,"year_source":"db","year_min":1924,"year_max":1924,"year_label":null,"structure":"木造2階一部平屋建、鉄板葺・銅板葺及び一部スレート葺、建築面積1014㎡","structure_material":"木造2階一部平屋建","registered":"2011.10.28(平成23.10.28)","register_no":"14 － 0171","desc":"箱根小涌谷に建ち、唐破風玄関を構えた主屋、洋風内装のラウンジ棟、客室を一列に配した月梅、田の字形に配した松竹、月梅と中庭を介して建つ浴場棟からなり、建築面積1014㎡を測る。温泉地の発展に伴う増築過程をよく示す老舗旅館の本館。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008832"},{"id":"00013513","register_sub_id":"101","register_pk":"504877","name":"湯浅物産館","kana":"ゆあさぶっさんかん","category":"産業3次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"神奈川県","address":"神奈川県鎌倉市雪ノ下一丁目272イ2他","lat":35.32235833,"lng":139.55385278,"geo_status":"db","era":"昭和11年","year":1936,"year_source":"db","year_min":1936,"year_max":1936,"year_label":null,"structure":"木造2階建、鉄板葺、建築面積246㎡","structure_material":"木造2階建","registered":"2021.02.04(令和3.02.04)","register_no":"14 － 0286","desc":"若宮大路に東面して建つ二階建の看板建築。間口六間、奥行一一間半で、店の奥にトップライト付きの吹抜けを設けた近代的なつくりとする。正面はスクラッチタイル貼とし、二階に六連の額縁飾付半円アーチ窓を配して意匠を凝らし、街路景観に彩りを添える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013513"},{"id":"00011662","register_sub_id":"101","register_pk":"210678","name":"龍宮殿本館","kana":"りゅうぐうでんほんかん","category":"産業3次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"神奈川県","address":"神奈川県足柄下郡箱根町元箱根字蛸川139-3","lat":35.210406,"lng":139.011223,"geo_status":"db","era":"昭和13年／昭和31年移築、平成28年改修","year":1938,"year_source":"db","year_min":1938,"year_max":1938,"year_label":null,"structure":"木造2階一部3階建、銅板葺、建築面積1348㎡","structure_material":"木造2階一部3階建","registered":"2017.06.28(平成29.06.28)","register_no":"14-0234","desc":"芦ノ湖の東岸に建つ。昭和初期に浜名湖弁天島に建てられたホテルを昭和三一年に当地に移築。平等院鳳凰堂を模した外観で、二階建の中央建物の両翼に三階建の望楼風建物を配する。伝統的な様式を模した吹抜け階段ホールを持つなど、外国人向けホテルの希少な例。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011662"},{"id":"00011098","register_sub_id":"101","register_pk":"205205","name":"秋山孝ポスター美術館長岡本館（旧長岡商業銀行宮内支店）","kana":"あきやまたかしぽすたーびじゅつかんながおかほんかん（きゅうながおかしょうぎょうぎんこうみやうちしてん）","category":"産業3次","subcategory":"建築物","type_guess":"店舗","type_guess_confidence":"high","period":"大正","pref":"新潟県","address":"新潟県長岡市宮内二丁目127-1","lat":37.420394,"lng":138.841663,"geo_status":"db","era":"大正14／昭和27移築、平成21改修","year":1925,"year_source":"db","year_min":1925,"year_max":1925,"year_label":null,"structure":"鉄筋コンクリート造平屋建、瓦葺、建築面積94㎡","structure_material":"鉄筋コンクリート造平屋建","registered":"2016.08.01(平成28.08.01)","register_no":"15 - 0440","desc":"旧三国街道に西面して建つ。鉄筋コンクリート造平屋建切妻造瓦葺。外壁は正面が洗出し、側面はタイル張り、窓枠は人造石研出しである。雁木は曳家の際鉄筋コンクリート造に改められたが、大正末の銀行建築の姿をよく残し、地域のシンボルとなっている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011098"},{"id":"00009135","register_sub_id":"101","register_pk":"164688","name":"麻屋高野店舗兼主屋","kana":"あさやたかのてんぽけんしゅおく","category":"産業3次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"昭和前","pref":"新潟県","address":"新潟県上越市東本町一丁目字善光寺町3-1他","lat":37.11934771,"lng":138.24664592,"geo_status":"db","era":"昭和12年","year":1937,"year_source":"db","year_min":1937,"year_max":1937,"year_label":null,"structure":"木造2階建、鉄板葺、建築面積118㎡","structure_material":"木造2階建","registered":"2012.02.23(平成24.02.23)","register_no":null,"desc":"通りに南面し、木造2階建、建築面積118平方メートル、切妻造鉄板葺である。1階はミセ、チャノマ、ザシキ、ドインを並べ、2階はチャノマ吹抜けの前後にマエニカイとウシロニカイを配し渡廊下でつなぐ。近代高田の町家において発展した空間構成を有する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009135"},{"id":"00009136","register_sub_id":"101","register_pk":"164689","name":"麻屋高野土蔵","kana":"あさやたかのどぞう","category":"産業3次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"high","period":"昭和前","pref":"新潟県","address":"新潟県上越市東本町一丁目字善光寺町3-1他","lat":37.11944407,"lng":138.24666377,"geo_status":"db","era":"昭和7年","year":1932,"year_source":"db","year_min":1932,"year_max":1932,"year_label":null,"structure":"土蔵造2階建、鉄板葺、建築面積52㎡","structure_material":"土蔵造2階建","registered":"2012.02.23(平成24.02.23)","register_no":null,"desc":"敷地後方に建つ、アマヤで覆われた土蔵で、建築面積52平方メートル、土蔵造2階建、切妻造鉄板葺である。土蔵周囲は主屋のトオリニワと連続する内部空間とし、積雪時の通路と作業場所を確保している。雪国における町家の特色と生活様態を示す家財蔵である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009136"},{"id":"00011929","register_sub_id":"101","register_pk":"210936","name":"荒惣内蔵","kana":"あらそううちぐら","category":"産業3次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"江戸","pref":"新潟県","address":"新潟県胎内市本町28","lat":38.051519,"lng":139.402788,"geo_status":"db","era":"江戸後期","year":1801,"year_source":"estimated","year_min":1751,"year_max":1830,"year_label":"江戸後期","structure":"土蔵造2階建、鋼板葺、建築面積35㎡","structure_material":"土蔵造2階建","registered":"2017.10.27(平成29.10.27)","register_no":"15-471","desc":"敷地中央の南寄りに東西棟で南面する。置屋根形式で、桁行八メートル、梁間四メートルで、一尺間隔で柱を立て、板を嵌める丁寧な造り。正面のみ両開扉と二階に片開窓を二所設け、三段の掛子塗とし、扉下部に桃の漆喰彫刻が施され珍しい造形を見せる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011929"},{"id":"00011927","register_sub_id":"101","register_pk":"210934","name":"荒惣店舗兼主屋","kana":"あらそうてんぽけんしゅおく","category":"産業3次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"江戸","pref":"新潟県","address":"新潟県胎内市本町28","lat":38.051479,"lng":139.403005,"geo_status":"db","era":"文政7年（1824）／明治前期・同34年増築、昭和40年頃改修","year":1824,"year_source":"db","year_min":1824,"year_max":1824,"year_label":null,"structure":"木造2階建、瓦葺、232㎡","structure_material":"木造2階建","registered":"2017.10.27(平成29.10.27)","register_no":"15-469","desc":"旧宿場町中条の中心にあり東面する。南側の通り土間に沿って、ミセ、茶の間、板の間を並べ、北に座敷二室を増築する。二階は床の間、床脇を備えた上の間と次の間を並べ、正面に縁側を設ける。ミセは北へも増築しコの字平面となり、繁栄の過程を示す大型町家。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011927"},{"id":"00011928","register_sub_id":"101","register_pk":"210935","name":"荒惣見世蔵","kana":"あらそうみせぐら","category":"産業3次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"明治","pref":"新潟県","address":"新潟県胎内市本町28","lat":38.051522,"lng":139.403049,"geo_status":"db","era":"明治34年","year":1901,"year_source":"db","year_min":1901,"year_max":1901,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積46㎡","structure_material":"土蔵造2階建","registered":"2017.10.27(平成29.10.27)","register_no":"15-470","desc":"敷地北に東西棟で建つ。桁行一〇メートル、梁間四・六メートルで、両妻面は両開扉を四段の掛子塗とし、内部は一尺角の棟持柱を中央に立て堅牢に造る。一階側面は海鼠壁で飾り、通りに面する二階北面は黒漆喰塗の両開の窓を三所開き、街路景観を重厚に形作る。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011928"},{"id":"00001592","register_sub_id":"101","register_pk":"102582","name":"行形亭裏門","kana":"いきなりやうらもん","category":"産業3次","subcategory":"その他工作物","type_guess":"塀・門","type_guess_confidence":"high","period":"江戸","pref":"新潟県","address":"新潟県新潟市中央区西大畑町573","lat":37.92665259,"lng":139.0405389,"geo_status":"db","era":"江戸末期","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"木造、鉄板葺、間口2.1m","structure_material":"木造","registered":"2000.04.28(平成12.04.28)","register_no":"15 － 0064","desc":"敷地北端の裏山の上に位置する。表門と同様の銅板葺のムクリ屋根を載せる。疎ら垂木，片開きの縦格子透し門で，その一枚戸に引き戸形式の潜戸を付ける。柱には念入りな面取りがなされ，裏庭の景観を引き締めている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001592"},{"id":"00001591","register_sub_id":"101","register_pk":"102581","name":"行形亭表門","kana":"いきなりやおもてもん","category":"産業3次","subcategory":"その他工作物","type_guess":"塀・門","type_guess_confidence":"high","period":"大正","pref":"新潟県","address":"新潟県新潟市中央区西大畑町573","lat":37.92610038,"lng":139.04106994,"geo_status":"db","era":"大正3","year":1914,"year_source":"db","year_min":1914,"year_max":1914,"year_label":null,"structure":"木造、鉄板葺、間口2.3m","structure_material":"木造","registered":"2000.04.28(平成12.04.28)","register_no":"15 － 0063","desc":"敷地の南東部に位置する。銅板葺の薄いムクリ屋根を載せた数寄屋風の門であるが，内側に広がった小屋根付きの控え板壁を伸ばして高麗門風の構えをとる。鶴の透し彫りが施された板欄間付きの縦格子透し門扉に気品が感じられる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001591"},{"id":"00001587","register_sub_id":"101","register_pk":"102577","name":"行形亭九番の間","kana":"いきなりやきゅうばんのま","category":"産業3次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"新潟県","address":"新潟県新潟市中央区西大畑町573","lat":37.92627786,"lng":139.04076796,"geo_status":"db","era":"明治10","year":1877,"year_source":"db","year_min":1877,"year_max":1877,"year_label":null,"structure":"木造平屋建、鉄板葺、建築面積29㎡","structure_material":"木造平屋建","registered":"2000.04.28(平成12.04.28)","register_no":"15 － 0059","desc":"離れ座敷に隣接する。一室の座敷に加えて玄関，廊下を備える独立した客室。木造平屋建，鉄板葺で，腰壁黒塗簓子下見板張，建物上部を真壁造りとする。建物後部は築山に載り，建物前面が懸造状に高い床束に載ることで，舞台装置的に庭に張り出す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001587"},{"id":"00001586","register_sub_id":"101","register_pk":"102576","name":"行形亭寿の間・二番の間","kana":"いきなりやことぶきのま・にばんのま","category":"産業3次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"新潟県","address":"新潟県新潟市中央区西大畑町573","lat":37.92649252,"lng":139.04057625,"geo_status":"db","era":"明治10","year":1877,"year_source":"db","year_min":1877,"year_max":1877,"year_label":null,"structure":"木造平屋建、鉄板葺、建築面積252㎡","structure_material":"木造平屋建","registered":"2000.04.28(平成12.04.28)","register_no":"15 － 0058","desc":"行形亭は新潟市内の代表的老舗料亭として知られている。この木造平屋建の座敷棟は，広大な敷地の最奥部に位置し庭と広く面する。木造平屋建，黒塗簓子下見板張，鉄板葺寄棟屋根で，大広間を中心に構成される寿の間が，主屋から連続する内部空間の終点となる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001586"},{"id":"00001585","register_sub_id":"101","register_pk":"102575","name":"行形亭三番の間","kana":"いきなりやさんばんのま","category":"産業3次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"新潟県","address":"新潟県新潟市中央区西大畑町573","lat":37.92661297,"lng":139.04082745,"geo_status":"db","era":"明治10","year":1877,"year_source":"db","year_min":1877,"year_max":1877,"year_label":null,"structure":"木造平屋建、鉄板葺、建築面積40㎡","structure_material":"木造平屋建","registered":"2000.04.28(平成12.04.28)","register_no":"15 － 0057","desc":"行形亭では敷地中央の池付の庭を囲むように各建物が配される。木造平屋建の三番の間は敷地の北側に位置し，その両端が広間及び二番の間と廊下で接続される。腰壁黒塗簓子下見板張，上部を真壁造りとする。数寄屋風の内部は掛込天井及び舟底天井の形式を取る。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001585"},{"id":"00001584","register_sub_id":"101","register_pk":"102574","name":"行形亭主屋","kana":"いきなりやしゅおく","category":"産業3次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"江戸","pref":"新潟県","address":"新潟県新潟市中央区西大畑町573","lat":37.92628093,"lng":139.04104766,"geo_status":"db","era":"江戸末期","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"木造2階建、鉄板葺、建築面積107㎡","structure_material":"木造2階建","registered":"2000.04.28(平成12.04.28)","register_no":"15 － 0056","desc":"料亭・行形亭は元禄年間の創業といわれる。総２階建の主屋の１階前面には，庇下の空間を利用したＬ字型の土間が配される。正面妻では上部の梁と小壁，下部の板壁と窓を効果的に組み合わせ，両側の２階庇の破風が意匠を引き立てている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001584"},{"id":"00001593","register_sub_id":"101","register_pk":"102583","name":"行形亭中門及び塀","kana":"いきなりやちゅうもんおよびへい","category":"産業3次","subcategory":"その他工作物","type_guess":"塀・門","type_guess_confidence":"high","period":"昭和前","pref":"新潟県","address":"新潟県新潟市中央区西大畑町573","lat":37.92616683,"lng":139.04076437,"geo_status":"db","era":"昭和3","year":1928,"year_source":"db","year_min":1928,"year_max":1928,"year_label":null,"structure":"木造、木羽葺、間口1.4m","structure_material":"木造","registered":"2000.04.28(平成12.04.28)","register_no":"15 － 0065","desc":"離れ座敷の庭を囲み，土蔵と対面する。間口４尺５寸の中門は自然木で棟木を支え，屋根は木羽葺，門扉は網代戸とし，瀟洒な印象を与える。塀は腰壁板張り，上部漆喰塗りとし，土蔵壁面と調和した意匠で，離れ座敷表玄関への通路を形成している。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001593"},{"id":"00001590","register_sub_id":"101","register_pk":"102580","name":"行形亭土蔵","kana":"いきなりやどぞう","category":"産業3次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"high","period":"昭和前","pref":"新潟県","address":"新潟県新潟市中央区西大畑町573","lat":37.926048,"lng":139.040802,"geo_status":"db","era":"昭和3","year":1928,"year_source":"db","year_min":1928,"year_max":1928,"year_label":null,"structure":"木造2階建、瓦葺、建築面積59㎡","structure_material":"木造2階建","registered":"2000.04.28(平成12.04.28)","register_no":"15 － 0062","desc":"離れ座敷と同時期に建設される。置屋根型式の桟瓦葺で，２階床部まで腰板が張られ，その上部を漆喰仕上げとする。道路側の妻面には鶴の鏝絵が施される。前面道路から見る黒板塀と黒松越しの土蔵は新潟の風情を表す代表的景観として親しまれている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001590"},{"id":"00001589","register_sub_id":"101","register_pk":"102579","name":"行形亭離れ座敷","kana":"いきなりやはなれざしき","category":"産業3次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"新潟県","address":"新潟県新潟市中央区西大畑町573","lat":37.92621535,"lng":139.04081138,"geo_status":"db","era":"昭和3","year":1928,"year_source":"db","year_min":1928,"year_max":1928,"year_label":null,"structure":"木造2階建、瓦葺、建築面積319㎡","structure_material":"木造2階建","registered":"2000.04.28(平成12.04.28)","register_no":"15 － 0061","desc":"敷地の南側に位置する木造２階建の建屋。入母屋造り，桟瓦葺，簓子下見板張で，和風を基調とした玄関には，多種の洋風照明器具，自然木を用いた階段手摺りなどに独特な造作を施している。また，内部の随所に，行形亭のシンボルである鶴を模した意匠が見られる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001589"},{"id":"00001588","register_sub_id":"101","register_pk":"102578","name":"行形亭湯殿","kana":"いきなりやゆどの","category":"産業3次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"新潟県","address":"新潟県新潟市中央区西大畑町573","lat":37.92606238,"lng":139.04065304,"geo_status":"db","era":"明治20","year":1887,"year_source":"db","year_min":1887,"year_max":1887,"year_label":null,"structure":"木造平屋建、鉄板葺、建築面積58㎡","structure_material":"木造平屋建","registered":"2000.04.28(平成12.04.28)","register_no":"15 － 0060","desc":"九番の間に隣接し，客用の浴室として設けられた，木造平屋建の建屋。前面の庇の下に通土間が配され，それに沿って脱衣室，廊下，浴室が並んでいる。脱衣室には床の間が設けられ，数寄屋風の意匠とし，浴室の天井には白漆喰で龍の鏝絵が描かれる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001588"},{"id":"00006272","register_sub_id":"101","register_pk":"107256","name":"井筒屋旅館主屋","kana":"いづつやりょかんしゅおく","category":"産業3次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"新潟県","address":"新潟県村上市小町221","lat":38.225994,"lng":139.478989,"geo_status":"db","era":"明治末期","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治末期","structure":"木造2階建、瓦葺、建築面積115㎡","structure_material":"木造2階建","registered":"2007.07.31(平成19.07.31)","register_no":"15 － 0257","desc":"西側道路に面して建つ近代の町家建築。桁行５間，梁間４間半規模の木造２階建で，切妻造，桟瓦葺とする。平入で，正面１階には下屋を，２階には縁を付ける。外壁は正面をモルタル仕上げとし，側面を縦板張とする。旧城下町町人地に建ち，町並みの景観に寄与。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006272"},{"id":"00010276","register_sub_id":"101","register_pk":"199049","name":"遠人村舎","kana":"えんじんそんしゃ","category":"産業3次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"新潟県","address":"新潟県三条市庭月501","lat":37.541094,"lng":139.104109,"geo_status":"db","era":"明治期／昭和12年・平成8年移築","year":1890,"year_source":"estimated","year_min":1868,"year_max":1912,"year_label":"明治期","structure":"木造平屋建、瓦葺、建築面積21㎡","structure_material":"木造平屋建","registered":"2014.12.19(平成26.12.19)","register_no":"15-0393","desc":"漢学者諸橋轍次が大漢和辞典編纂を手がけた建物。切妻造で屋根は一文字瓦葺の周囲を金属板葺とする。四畳半と三畳の二室の北西に半間幅の廊下を廻らす。外壁にスギ皮を張り、内部造作に吟味された丸太材を使うなど、漢学者の書斎に相応しく趣ある意匠となる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010276"},{"id":"00003395","register_sub_id":"101","register_pk":"104385","name":"大橋屋主屋及び土蔵","kana":"おおはしやしゅおくおよびどぞう","category":"産業3次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"high","period":"昭和前","pref":"新潟県","address":"新潟県新潟市中央区本町通十一番町1813","lat":37.927387,"lng":139.047745,"geo_status":"db","era":"昭和10","year":1935,"year_source":"db","year_min":1935,"year_max":1935,"year_label":null,"structure":"木造3階一部2階建、瓦葺、建築面積323㎡","structure_material":"木造3階一部2階建","registered":"2003.07.01(平成15.07.01)","register_no":"15 － 0156","desc":"市中心部の本町通に面する短冊状の敷地にたつ。妻入で，正面２階に半円アーチと矩形の窓を並置し，壁面を銅板網代張り，その上部に２重の入母屋屋根を見せる。内部は二・三階に客室を設け，各座敷の天井や開口部などに意匠を凝らし変化に富む造作を見せる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003395"},{"id":"00010761","register_sub_id":"101","register_pk":"201596","name":"割烹東忠上の蔵","kana":"かっぽうとうちゅううえのくら","category":"産業3次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"high","period":"明治","pref":"新潟県","address":"新潟県小千谷市元町538-1","lat":37.308484,"lng":138.798462,"geo_status":"db","era":"明治前期／昭和前期改修","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治前期","structure":"土蔵造2階建、鋼板葺、建築面積41㎡","structure_material":"土蔵造2階建","registered":"2015.11.17(平成27.11.17)","register_no":"15 ‐ 0422","desc":"本館北奥部と妻面を接して建つ、切妻造の二階建土蔵。上下階とも両妻面を張出し、外壁は主体部二階を漆喰塗とする他は下見板を張る。戦前に一階を撞球室としたため洋風持送などの内装を持ち、北妻に半切妻屋根の玄関を設ける。割烹に附属した娯楽施設の遺構","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010761"},{"id":"00010760","register_sub_id":"101","register_pk":"201595","name":"割烹東忠別館","kana":"かっぽうとうちゅうべっかん","category":"産業3次","subcategory":"建築物","type_guess":"料亭","type_guess_confidence":"high","period":"昭和前","pref":"新潟県","address":"新潟県小千谷市元町538-1","lat":37.308445,"lng":138.798662,"geo_status":"db","era":"昭和前期","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和前期","structure":"木造2階建、瓦葺、建築面積107㎡","structure_material":"木造2階建","registered":"2015.11.17(平成27.11.17)","register_no":"15 ‐ 0421","desc":"敷地形状により本館と斜めに接続し、スキップフロア状の動線で連絡するため、変化に富んだ空間構成を持つ。一階は広間二室、二階は大広間とし、庭に面して縁を廻らし、開口を広くとる。座敷飾は大振りで、かつ洗練された意匠になる、瀟洒で上質な和風建築。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010760"},{"id":"00010759","register_sub_id":"101","register_pk":"201594","name":"割烹東忠本館","kana":"かっぽうとうちゅうほんかん","category":"産業3次","subcategory":"建築物","type_guess":"料亭","type_guess_confidence":"high","period":"江戸","pref":"新潟県","address":"新潟県小千谷市元町538-1","lat":37.308416,"lng":138.798598,"geo_status":"db","era":"江戸末期／昭和39改修","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"木造3階建、鋼板葺、建築面積200㎡","structure_material":"木造3階建","registered":"2015.11.17(平成27.11.17)","register_no":"15 ‐ 0420","desc":"湯殿川畔の傾斜地に建つ木造三階建の割烹で、江戸末期建築の二階建に三階大広間を増築した。外観は建ちの高い真壁造で、一・二階に大小一〇室ほどの客室などを配し、要所に良材を用いた座敷飾を備える。小千谷縮や養鯉業による当地の繁栄を伝える料理屋建築。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010759"},{"id":"00003406","register_sub_id":"101","register_pk":"104396","name":"割烹みよや","kana":"かっぽうみよや","category":"産業3次","subcategory":"建築物","type_guess":"料亭","type_guess_confidence":"high","period":"大正","pref":"新潟県","address":"新潟県三島郡出雲崎町大字羽黒町101-1","lat":37.54438498,"lng":138.69031903,"geo_status":"db","era":"大正初期","year":1917,"year_source":"estimated","year_min":1912,"year_max":1918,"year_label":"大正初期","structure":"木造2階建、瓦葺、建築面積37㎡","structure_material":"木造2階建","registered":"2003.07.01(平成15.07.01)","register_no":"15 － 0167","desc":"日本海に近い旧北国街道に面して建つ。妻入で，欄間窓付縦長窓などの前面にベランダが付き，上部にハンマービーム風の妻飾りを設ける。２階内部の天井・壁面に施された漆喰の格縁やモールディング，外壁の天使をあしらった鏝絵などの仕上に高度な技を見せる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003406"},{"id":"00005112","register_sub_id":"101","register_pk":"106102","name":"割烹吉源主屋","kana":"かっぽうよしげんしゅおく","category":"産業3次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"昭和前","pref":"新潟県","address":"新潟県村上市寺町1437","lat":38.22457994,"lng":139.47655991,"geo_status":"db","era":"昭和4","year":1929,"year_source":"db","year_min":1929,"year_max":1929,"year_label":null,"structure":"木造2階一部平屋建、瓦葺、建築面積566㎡","structure_material":"木造2階一部平屋建","registered":"2005.12.26(平成17.12.26)","register_no":"15 － 0189","desc":"寺町の通りに北面して建つ。入母屋造，桟瓦葺のたちの高い２階建の西に切妻造，桟瓦葺の２階建を雁行させ，背後に１５畳４室を並べた南北棟の平屋建を延ばす。内部は，２階の洋風大広間を中心とした良質なつくり。棟札から年代と棟梁「遠藤鉀子郎」が判明。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005112"},{"id":"00010950","register_sub_id":"101","register_pk":"208921","name":"環翠楼大正の間","kana":"かんすいろうたいしょうのま","category":"産業3次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"大正","pref":"新潟県","address":"新潟県阿賀野市村杉字薬師平4520","lat":37.800197,"lng":139.29007,"geo_status":"db","era":"大正4","year":1915,"year_source":"db","year_min":1915,"year_max":1915,"year_label":null,"structure":"木造2階建、瓦葺、建築面積116㎡","structure_material":"木造2階建","registered":"2016.02.25(平成28.02.25)","register_no":"15-0424","desc":"村杉温泉の老舗旅館で、杉林に囲まれた敷地に構える。木造二階建で横長平面を持つ客室棟で、中央を突出させて玄関ポーチを設ける。東の広縁を介して各室に入るようになっている。軒天井などに洋風意匠も見られる。丁寧な造作になる数寄屋風の内装を持つ。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010950"},{"id":"00013705","register_sub_id":"101","register_pk":"504969","name":"環翠楼中広間","kana":"かんすいろうちゅうひろま","category":"産業3次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和後","pref":"新潟県","address":"新潟県阿賀野市村杉字薬師平4520","lat":37.80020833,"lng":139.290025,"geo_status":"db","era":"昭和43年","year":1968,"year_source":"db","year_min":1968,"year_max":1968,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積159㎡","structure_material":"木造平屋建","registered":"2021.02.26(令和3.02.26)","register_no":"15 － 549","desc":"南北棟で平屋建寄棟造桟瓦葺。本館から続く廊下からホールに出、北に向かって下座敷、上座敷が続く。西脇は脇座敷である。北・東に広縁を廻し、額入障子を建てる。小壁のせいが高く、貫を二段廻らし開放感のある空間をつくる。敷地北寄りの景観を形成する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013705"},{"id":"00013704","register_sub_id":"101","register_pk":"504968","name":"環翠楼臨泉閣","kana":"かんすいろうりんせんかく","category":"産業3次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"新潟県","address":"新潟県阿賀野市村杉字薬師平4520","lat":37.80019722,"lng":139.29051667,"geo_status":"db","era":"明治後期","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治後期","structure":"木造2階建、瓦葺、建築面積71㎡","structure_material":"木造2階建","registered":"2021.02.26(令和3.02.26)","register_no":"15 － 548","desc":"新潟平野の山間部にある村杉温泉に所在。敷地中央の高台に位置し、石階でアプローチする。二階建入母屋造桟瓦葺で一、二階とも八畳座敷二室からなり四周に縁を廻らす。床構えは床脇を地袋天袋とした端正な構え。三方にガラス戸を建て庭を望む近代和風の好例。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013704"},{"id":"00003081","register_sub_id":"101","register_pk":"104071","name":"吉川家住宅店舗","kana":"きっかわけじゅうたくてんぽ","category":"産業3次","subcategory":"建築物","type_guess":"店舗","type_guess_confidence":"high","period":"明治","pref":"新潟県","address":"新潟県村上市大町195","lat":38.22432962,"lng":139.47867617,"geo_status":"db","era":"明治25頃","year":1892,"year_source":"db","year_min":1892,"year_max":1892,"year_label":null,"structure":"木造2階建、瓦葺、建築面積37㎡","structure_material":"木造2階建","registered":"2003.01.31(平成15.01.31)","register_no":"15 － 0142","desc":"村上城下旧町人地の中心的通りに面して建つ。桁行２間半梁間４間半規模，南北棟，切妻造，桟瓦葺の町家で，明治２５年の大火後の再建と伝える。近年，北側の増築に際してファサードが伝統的意匠に改装され，大町通りの街路景観整備の核的存在となっている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003081"},{"id":"00005598","register_sub_id":"101","register_pk":"106586","name":"喜八屋旅館石蔵","kana":"きはちやりょかんいしぐら","category":"産業3次","subcategory":"建築物","type_guess":"旅館","type_guess_confidence":"high","period":"大正","pref":"新潟県","address":"新潟県佐渡市小木町55-1他","lat":37.816284,"lng":138.279861,"geo_status":"db","era":"大正末期","year":1922,"year_source":"estimated","year_min":1919,"year_max":1926,"year_label":"大正末期","structure":"石造2階建、建築面積26㎡","structure_material":"石造2階建","registered":"2006.08.03(平成18.08.03)","register_no":"15 － 0203","desc":"別館の北東に位置し，桁行２間半，梁間２間半の規模で，石造２階建，ＲＣ造の陸屋根とする。食器等の蔵であるが，屋上は別館客室のテラスとして使われた。外壁は大谷石を積み，破れ目地を見せる。当初は敷地の最後部に位置し，海岸に面して建っていた。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005598"},{"id":"00005596","register_sub_id":"101","register_pk":"106584","name":"喜八屋旅館旧館","kana":"きはちやりょかんきゅうかん","category":"産業3次","subcategory":"建築物","type_guess":"旅館","type_guess_confidence":"high","period":"明治","pref":"新潟県","address":"新潟県佐渡市小木町55-1他","lat":37.816372,"lng":138.279633,"geo_status":"db","era":"明治38／昭和3増築","year":1905,"year_source":"db","year_min":1905,"year_max":1905,"year_label":null,"structure":"木造5階建、鉄板葺、建築面積115㎡","structure_material":"木造5階建","registered":"2006.08.03(平成18.08.03)","register_no":"15 － 0201","desc":"小木港海岸線に平行して通る国道に西面して建つ。桁行１２．１ｍ，梁間９．１ｍの規模で，木造５階建，寄棟造，鉄板葺とする。１階に居間等を配し，２階，４階，５階を客室とする。２階正面はせり出しとし，３階以上は増築であり，旧正面の形式を残す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005596"},{"id":"00005597","register_sub_id":"101","register_pk":"106585","name":"喜八屋旅館別館（裏三階）","kana":"きはちやりょかんべっかん（うらさんかい）","category":"産業3次","subcategory":"建築物","type_guess":"旅館","type_guess_confidence":"high","period":"大正","pref":"新潟県","address":"新潟県佐渡市小木町55-1他","lat":37.816273,"lng":138.2798,"geo_status":"db","era":"大正末期","year":1922,"year_source":"estimated","year_min":1919,"year_max":1926,"year_label":"大正末期","structure":"木造3階建、鉄板葺、建築面積43㎡","structure_material":"木造3階建","registered":"2006.08.03(平成18.08.03)","register_no":"15 － 0202","desc":"旧館の東裏に建ち，桁行８．２ｍ，梁間４．５ｍの規模で，木造３階建，寄棟造，鉄板葺，平入とする。１階を物置，２階を新館への通路等，３階を客室２間とする。東側の海の眺望を重視して建てられ，眺望を確保しようとする当時の旅館の姿を知ることができる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005597"},{"id":"00006448","register_sub_id":"101","register_pk":"107431","name":"旧石崎家住宅（石泉荘）離れ座敷","kana":"きゅういしざきけじゅうたく（せきせんそう）はなれざしき","category":"産業3次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"新潟県","address":"新潟県新発田市諏訪町3-11-21","lat":37.941097,"lng":139.328537,"geo_status":"db","era":"明治38／昭和初期増築","year":1905,"year_source":"db","year_min":1905,"year_max":1905,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積87㎡","structure_material":"木造平屋建","registered":"2007.10.02(平成19.10.02)","register_no":"15 － 0261","desc":"屋敷地内を南北に流れる新発田川の右岸に建つ。もと料亭の離れ座敷。主体部は桁行４間半、梁間２間半、南北棟、切妻造、桟瓦葺の木造平屋建で、南・西面に縁を廻し、東面に玄関、北面に水回り、北西川端に４畳半を張り出す。川に対して開放的なつくりに特徴。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006448"},{"id":"00013518","register_sub_id":"101","register_pk":"504882","name":"旧片桐家住宅主屋","kana":"きゅうかたぎりけじゅうたくおもや","category":"産業3次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"新潟県","address":"新潟県新潟市中央区上大川前通十二番町2742-3","lat":37.92859167,"lng":139.04890278,"geo_status":"db","era":"明治35年","year":1902,"year_source":"db","year_min":1902,"year_max":1902,"year_label":null,"structure":"木造平屋建、瓦葺一部鉄板葺、建築面積196㎡","structure_material":"木造平屋建","registered":"2021.02.04(令和3.02.04)","register_no":"15 － 0531","desc":"新潟市の中心部に建つ商家。平屋建正面寄棟造背面切妻造桟瓦葺。角地に建ち、東正面はガラス戸を建て中央を戸口とし、南側面は板壁とする。玄関脇をミセとし、奥を二列六室として手前上手に座敷をおく。庭木等とともに表通りの景観を形成。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013518"},{"id":"00013519","register_sub_id":"101","register_pk":"504883","name":"旧片桐家住宅土蔵","kana":"きゅうかたぎりけじゅうたくどぞう","category":"産業3次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"high","period":"明治","pref":"新潟県","address":"新潟県新潟市中央区上大川前通十二番町2742-1","lat":37.92861667,"lng":139.048725,"geo_status":"db","era":"明治前期","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治前期","structure":"土蔵造2階建、瓦葺、建築面積37㎡","structure_material":"土蔵造2階建","registered":"2021.02.04(令和3.02.04)","register_no":"15 － 0532","desc":"主屋の西背後に建つ。二階建切妻造桟瓦葺。周囲の下屋は後の改修。平入の戸口を掛子塗の開戸とし、通りに面した妻側に引違いの窓を開ける。一、二階とも一室で柱間に板を張る。小屋は和小屋で中央の小屋梁を短い梁で受ける。主屋とともに通りの景観を形成。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013519"},{"id":"00015166","register_sub_id":"101","register_pk":"530590","name":"旧割烹有明奥棟","kana":"きゅうかっぽうありあけおくとう","category":"産業3次","subcategory":"建築物","type_guess":"料亭","type_guess_confidence":"high","period":"昭和前","pref":"新潟県","address":"新潟県新潟市中央区古町通九番町1463","lat":37.92563333,"lng":139.04627778,"geo_status":"db","era":"昭和3年／昭和33年・同40年代・令和3年改修","year":1928,"year_source":"db","year_min":1928,"year_max":1928,"year_label":null,"structure":"木造2階建、瓦葺、建築面積140㎡","structure_material":"木造2階建","registered":"2024.12.03(令和6.12.03)","register_no":"15 - 0597","desc":"中棟の西に位置する奥棟。二階建片寄棟造桟瓦葺の東に切妻造を接続し全体Ｌ字の棟とする。北側路地に面する外観は竪板張、格子窓、丸太垂木の庇など数寄屋風。内部一階は土間と小上り、二階に床構え付き座敷を三室配し、床柱に銘木を用いた華やかな料亭建築。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00015166"},{"id":"00015164","register_sub_id":"101","register_pk":"530588","name":"旧割烹有明表棟","kana":"きゅうかっぽうありあけおもてとう","category":"産業3次","subcategory":"建築物","type_guess":"料亭","type_guess_confidence":"high","period":"明治","pref":"新潟県","address":"新潟県新潟市中央区古町通九番町1463","lat":37.92564722,"lng":139.04619722,"geo_status":"db","era":"明治43年／昭和33年増築、同40年代改修","year":1910,"year_source":"db","year_min":1910,"year_max":1910,"year_label":null,"structure":"木造2階建、瓦葺、建築面積222㎡","structure_material":"木造2階建","registered":"2024.12.03(令和6.12.03)","register_no":"15 - 0595","desc":"古町の東新道に東面する旧料亭の表棟。二階建寄棟造妻入桟瓦葺で、正面北寄りに起り付き入母屋玄関を付し、北側路地に二階壁面を張出す。二階は南面側に四室の続き間を配し、各室には床と棚を設え、室境に千鳥などの透し彫の板欄間を飾った上質な料亭建築。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00015164"},{"id":"00015165","register_sub_id":"101","register_pk":"530589","name":"旧割烹有明中棟","kana":"きゅうかっぽうありあけなかとう","category":"産業3次","subcategory":"建築物","type_guess":"料亭","type_guess_confidence":"high","period":"大正","pref":"新潟県","address":"新潟県新潟市中央区古町通九番町1463","lat":37.92563611,"lng":139.04623333,"geo_status":"db","era":"大正13年／昭和33年増築、令和4年改修","year":1924,"year_source":"db","year_min":1924,"year_max":1924,"year_label":null,"structure":"木造2階建、瓦葺、建築面積140㎡","structure_material":"木造2階建","registered":"2024.12.03(令和6.12.03)","register_no":"15 - 0596","desc":"表棟の西に中庭を挟んで位置する座敷棟。二階建寄棟造平入桟瓦葺で、表棟と渡り廊下で繋ぐ。二階に配する十八畳の客間は、床、棚、平書院を備え、床柱に大径の瘤付丸太を用い、床脇に円窓を開けるなど数寄屋風の意匠とし、大正の豪気な気風を伝える料亭建築。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00015165"},{"id":"00014350","register_sub_id":"101","register_pk":"511339","name":"旧酢屋呉服店店舗兼主屋","kana":"きゅうすやごふくてんてんぽけんおもや","category":"産業3次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"新潟県","address":"新潟県上越市中央三丁目976-2","lat":37.17825,"lng":138.24493611,"geo_status":"db","era":"明治41年／昭和前期改修","year":1908,"year_source":"db","year_min":1908,"year_max":1908,"year_label":null,"structure":"木造2階建、瓦葺、鉄板葺、建築面積192㎡","structure_material":"木造2階建","registered":"2022.10.31(令和4.10.31)","register_no":"15 - 0573","desc":"直江津の中町通に西面する呉服店の店舗兼住宅。土蔵が通りから後退するため、店舗正側面の入母屋造、軒の出桁造、霧除庇の豪壮な外観を見せる。正面雁木、内蔵が面する茶の間吹抜は雪国らしい構成。二階二〇畳座敷は客を招いて祇園祭を高欄越しに観覧した。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014350"},{"id":"00004950","register_sub_id":"101","register_pk":"105940","name":"旧第四銀行住吉町支店","kana":"きゅうだいしぎんこうすみよしちょうしてん","category":"産業3次","subcategory":"建築物","type_guess":"店舗","type_guess_confidence":"high","period":"昭和前","pref":"新潟県","address":"新潟県新潟市中央区柳島町2-10","lat":37.93053359,"lng":139.05808489,"geo_status":"db","era":"昭和2／平成15移築","year":1927,"year_source":"db","year_min":1927,"year_max":1927,"year_label":null,"structure":"鉄筋コンクリート造2階一部3階建、建築面積537㎡","structure_material":"鉄筋コンクリート造2階一部3階建","registered":"2005.11.10(平成17.11.10)","register_no":"15 － 0186","desc":"重厚な古典主義様式の銀行建築。２階建で，躯体は鉄筋コンクリート造，外壁に花崗岩を張って石造風とし，コーニスを廻す。正面入口にはイオニア式列柱４本を並べ，柱間の壁上部アーチ型窓とする。当初の外装材，内部の造作をよく保存している。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004950"},{"id":"00007736","register_sub_id":"101","register_pk":"108718","name":"旧高野寫眞舘（高野家住宅主屋）","kana":"きゅうたかのしゃしんかん（たかのけじゅうたくしゅおく）","category":"産業3次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"昭和前","pref":"新潟県","address":"新潟県糸魚川市大町2-101-1他","lat":37.0454317,"lng":137.86141074,"geo_status":"db","era":"昭和3／昭和29改修","year":1928,"year_source":"db","year_min":1928,"year_max":1928,"year_label":null,"structure":"鉄筋コンクリート造2階建、瓦葺、建築面積228㎡","structure_material":"鉄筋コンクリート造2階建","registered":"2009.08.07(平成21.08.07)","register_no":"15-0312","desc":"糸魚川駅前の市街地に東面して建つ。桁行１５ｍ梁間９．９ｍの鉄筋コンクリート造２階建で、正面に玄関ポ－チ、背面に物置、北面に土蔵などを付設。寄棟造妻入桟瓦葺。外壁はモルタル塗で、柱型をあらわし、軒蛇腹をまわす。簡明な意匠になる昭和初期の写真館。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007736"},{"id":"00010758","register_sub_id":"101","register_pk":"201593","name":"旧外山虎松商店店舗兼主屋","kana":"きゅうとやまとらまつしょうてんてんぽけんしゅおく","category":"産業3次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"昭和中","pref":"新潟県","address":"新潟県三条市神明町1669","lat":37.629541,"lng":138.961391,"geo_status":"db","era":"昭和27頃／昭和40年代・平成26改修","year":1952,"year_source":"db","year_min":1952,"year_max":1952,"year_label":null,"structure":"木造2階一部平屋建、瓦葺、建築面積99㎡、塀付","structure_material":"木造2階一部平屋建","registered":"2015.11.17(平成27.11.17)","register_no":"15 ‐ 0419","desc":"五十嵐川沿いの三条市街地に所在し、三叉路の角地に建つ。木造二階建で、通りに面して縦長窓を配したパラペットを立上げ、コーニスを廻らせる。北辺には看板を取り付けた塀が続く。戦後間もなく復興した商店建築で、地域のランドマークとして親しまれる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010758"},{"id":"00010275","register_sub_id":"101","register_pk":"199048","name":"旧新光屋米店精米所","kana":"きゅうにっこうやこめてんせいまいじょ","category":"産業3次","subcategory":"建築物","type_guess":"工場","type_guess_confidence":"high","period":"大正","pref":"新潟県","address":"新潟県三条市仲之町1800","lat":37.62959587,"lng":138.9633021,"geo_status":"db","era":"大正期／平成25年改修","year":1912,"year_source":"db","year_min":1912,"year_max":1912,"year_label":null,"structure":"煉瓦造平屋建、瓦葺、建築面積120㎡","structure_material":"煉瓦造平屋建","registered":"2014.12.19(平成26.12.19)","register_no":"15-0392","desc":"店舗兼主屋の背面に南北棟で建つ。煉瓦造平屋建で、壁面はイギリス積としてコーニスを廻らし、出入口上部を半円アーチ、窓などの開口部分は欠円アーチとする。小屋組はキングポストトラスを組む。三条市中心部において希少な、戦前期に遡る煉瓦造建築である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010275"},{"id":"00010274","register_sub_id":"101","register_pk":"199047","name":"旧新光屋米店店舗兼主屋","kana":"きゅうにっこうやこめてんてんぽけんしゅおく","category":"産業3次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"昭和前","pref":"新潟県","address":"新潟県三条市仲之町1800","lat":37.629468,"lng":138.96331387,"geo_status":"db","era":"昭和3年頃／昭和中期・平成25年改修","year":1928,"year_source":"db","year_min":1928,"year_max":1928,"year_label":null,"structure":"木造2階建、瓦葺、建築面積126㎡","structure_material":"木造2階建","registered":"2014.12.19(平成26.12.19)","register_no":"15-0391","desc":"市街中心の商店街に南面して建つ二階建町家で、入母屋の妻面を見せる。一階正面を雁木状の歩道、内部手前を土間のミセとし、東に通り土間を通して奥に事務室が続き、二階は座敷を配する。高い内部空間をもち、平面形式などに地方的特色を備えた近代の町家。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010274"},{"id":"00014790","register_sub_id":"101","register_pk":"519048","name":"旧若林医院西洋館","kana":"きゅうわかばやしいいんせいようかん","category":"産業3次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"大正","pref":"新潟県","address":"新潟県佐渡市畑野字高野甲717-2","lat":37.98687222,"lng":138.38888056,"geo_status":"db","era":"大正2年頃","year":1913,"year_source":"db","year_min":1913,"year_max":1913,"year_label":null,"structure":"木造2階建、瓦葺、建築面積69㎡","structure_material":"木造2階建","registered":"2024.03.06(令和6.03.06)","register_no":"15 - 0594","desc":"日本館北西に接続する２階建寄棟造の南北棟。北妻窓上部の軒を切上げ切妻破風を付す。南西に玄関を設け、各階幅１間の片廊下の西に部屋を配し、１階は続き間座敷、２階は２室の洋室とする。通りに面したスティックスタイルの外観が地域の歴史的景観を形成。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014790"},{"id":"00014789","register_sub_id":"101","register_pk":"519047","name":"旧若林医院日本館","kana":"きゅうわかばやしいいんにほんかん","category":"産業3次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"大正","pref":"新潟県","address":"新潟県佐渡市畑野字高野甲717-2","lat":37.98676389,"lng":138.38885,"geo_status":"db","era":"大正2年頃","year":1913,"year_source":"db","year_min":1913,"year_max":1913,"year_label":null,"structure":"木造2階建、瓦葺、建築面積151㎡","structure_material":"木造2階建","registered":"2024.03.06(令和6.03.06)","register_no":"15 - 0593","desc":"小倉川北岸の角地に位置するかつての医院。２階建入母屋造平入桟瓦葺の日本館は南面に大小の玄関を設け、切妻造屋根を付す。一階は東西に中廊下を通し北東隅を土間の診療室とし、二階には座敷を３室配す。ガラス戸を多く用いた外観が地域景観を特徴づける。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014789"},{"id":"00012138","register_sub_id":"101","register_pk":"352937","name":"越乃雪本舗大和屋店舗兼主屋","kana":"こしのゆきほんぽやまとやてんぽけんしゅおく","category":"産業3次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"昭和中","pref":"新潟県","address":"新潟県長岡市柳原町3-3","lat":37.446242,"lng":138.844136,"geo_status":"db","era":"昭和22年頃／昭和20年代後半・昭和40年頃増築、昭和56年改修","year":1947,"year_source":"db","year_min":1947,"year_max":1947,"year_label":null,"structure":"木造2階建、瓦葺、建築面積81㎡","structure_material":"木造2階建","registered":"2018.03.27(平成30.03.27)","register_no":"15 - 0473","desc":"市街地に位置する。木造二階建で、一階は前面土間で、通り土間に沿ってミセ、ブツマ、居室を、二階に二室を設ける。ミセには竹や磨き丸太を用いた床の間を設け、数寄屋風の意匠をみせる。切妻造妻入で、正面に雁木を付し、伝統的な表構えをもつ商家。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012138"},{"id":"00011097","register_sub_id":"101","register_pk":"205204","name":"小松屋旅館奥座敷棟","kana":"こまつやりょかんおくざしきとう","category":"産業3次","subcategory":"建築物","type_guess":"旅館","type_guess_confidence":"high","period":"昭和中","pref":"新潟県","address":"新潟県新潟市西蒲区岩室温泉字居掛681","lat":37.73706,"lng":138.837954,"geo_status":"db","era":"昭和32／昭和45・同53改修","year":1957,"year_source":"db","year_min":1957,"year_max":1957,"year_label":null,"structure":"木造2階建、瓦葺一部鉄板葺、建築面積84㎡","structure_material":"木造2階建","registered":"2016.08.01(平成28.08.01)","register_no":"15 - 0439","desc":"本館の西側にあり、渡廊下によって接続される。木造二階建、南北方向の棟とし、南側は入母屋造、北側は切妻造とする。周囲を庭に囲まれ上質な空間を創出している。階段や床の間などにケヤキ材を多用するとともに、面皮や皮付材なども用い凝った造作としている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011097"},{"id":"00011096","register_sub_id":"101","register_pk":"205203","name":"小松屋旅館表座敷棟","kana":"こまつやりょかんおもてざしきとう","category":"産業3次","subcategory":"建築物","type_guess":"旅館","type_guess_confidence":"high","period":"大正","pref":"新潟県","address":"新潟県新潟市西蒲区岩室温泉字居掛681","lat":37.736914,"lng":138.838234,"geo_status":"db","era":"大正14／昭和45・同53改修","year":1925,"year_source":"db","year_min":1925,"year_max":1925,"year_label":null,"structure":"木造平屋建、瓦葺一部銅板葺、建築面積37㎡","structure_material":"木造平屋建","registered":"2016.08.01(平成28.08.01)","register_no":"15 - 0438","desc":"敷地の南側、本館に向かって左側に東西棟で建つ。木造平屋建、入母屋造桟瓦葺で、中庭に面して閑静な佇まいをみせている。床の間の落掛、狆潜り、違棚の束や筆返しなどに、敷地内にあった老木からとったという黒柿を多用しており、凝った造作となっている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011096"},{"id":"00011095","register_sub_id":"101","register_pk":"205202","name":"小松屋旅館広間棟","kana":"こまつやりょかんひろまとう","category":"産業3次","subcategory":"建築物","type_guess":"旅館","type_guess_confidence":"high","period":"大正","pref":"新潟県","address":"新潟県新潟市西蒲区岩室温泉字居掛681","lat":37.736952,"lng":138.838082,"geo_status":"db","era":"大正3／昭和45改修","year":1914,"year_source":"db","year_min":1914,"year_max":1914,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積56㎡","structure_material":"木造平屋建","registered":"2016.08.01(平成28.08.01)","register_no":"15 - 0437","desc":"本館の南東に接続して建ち、東西に庭を配して落ち着いた佇まいをみせる。切妻造桟瓦葺、平屋建、南北棟である。床柱に神代欅、天袋框に黒柿など銘木を用いながらも平明な構成としている。また八畳の天井は三枚の板で張られており、大胆な意匠となっている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011095"},{"id":"00011094","register_sub_id":"101","register_pk":"205201","name":"小松屋旅館本館","kana":"こまつやりょかんほんかん","category":"産業3次","subcategory":"建築物","type_guess":"旅館","type_guess_confidence":"high","period":"昭和中","pref":"新潟県","address":"新潟県新潟市西蒲区岩室温泉字居掛681","lat":37.737017,"lng":138.838193,"geo_status":"db","era":"昭和26／昭和45・同53改修","year":1951,"year_source":"db","year_min":1951,"year_max":1951,"year_label":null,"structure":"木造2階建、瓦葺、建築面積154㎡","structure_material":"木造2階建","registered":"2016.08.01(平成28.08.01)","register_no":"15 - 0436","desc":"彌彦神社参詣の宿場として栄えた岩室温泉にある老舗旅館。北国街道から少し奥まった位置に東面して建ち、入母屋造の玄関を突き出す。屋根は東側を入母屋造、西側を切妻造とする。二階には客室三室を並べ、要所に銘木を用い、凝った造作としている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011094"},{"id":"00001570","register_sub_id":"101","register_pk":"102560","name":"佐野商店店舗兼住宅","kana":"さのしょうてんてんぽけんじゅうたく","category":"産業3次","subcategory":"建築物","type_guess":"店舗","type_guess_confidence":"high","period":"昭和前","pref":"新潟県","address":"新潟県新潟市中央区沼垂東4-5622","lat":37.92336128,"lng":139.06763724,"geo_status":"db","era":"昭和12","year":1937,"year_source":"db","year_min":1937,"year_max":1937,"year_label":null,"structure":"木造2階建、瓦葺、建築面積60㎡","structure_material":"木造2階建","registered":"2000.04.28(平成12.04.28)","register_no":"15 － 0042","desc":"雑貨商を営む佐野商店の店舗兼住宅で，木造総二階建，寄棟造・桟瓦葺で，昭和１２年の建設と伝える。軒をせがい造りとし，一階・二階の開口部に庇を設け，外壁を縦板張とする。直交する街路の一角に建ち，この地域の伝統的な町家の形式をよく保持している。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001570"},{"id":"00008842","register_sub_id":"101","register_pk":"162285","name":"三条市水道局大崎浄水場送水ポンプ室","kana":"さんじょうしすいどうきょくおおさきじょうすいじょうそうすいぽんぷしつ","category":"産業3次","subcategory":"建築物","type_guess":"事務所","type_guess_confidence":"low","period":"昭和前","pref":"新潟県","address":"新潟県三条市中新4420-3","lat":37.60896509,"lng":138.99710529,"geo_status":"db","era":"昭和8年","year":1933,"year_source":"db","year_min":1933,"year_max":1933,"year_label":null,"structure":"鉄筋コンクリート造平屋一部地下1階建、建築面積199㎡","structure_material":"鉄筋コンクリート造平屋一部地下1階建","registered":"2011.10.28(平成23.10.28)","register_no":"15 － 0351","desc":"調整池の北側に建ち、浄水を配水池に圧送する施設。鉄筋コンクリート造平屋建、一部地下1階、東西20ｍ南北11.4ｍ、西面に玄関を突出する。外壁は漆喰仕上げで窓に半円アーチを象り、内部は腰壁をタイル張とする。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008842"},{"id":"00008840","register_sub_id":"101","register_pk":"162283","name":"三条市水道局大崎浄水場着水井（送水井）","kana":"さんじょうしすいどうきょくおおさきじょうすいじょうちゃくすいせい（そうすいせい）","category":"産業3次","subcategory":"土木構造物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"新潟県","address":"新潟県三条市中新4420-3","lat":37.60869924,"lng":138.99758401,"geo_status":"db","era":"昭和8年","year":1933,"year_source":"db","year_min":1933,"year_max":1933,"year_label":null,"structure":"鉄筋コンクリート造、面積10㎡","structure_material":"鉄筋コンクリート造","registered":"2011.10.28(平成23.10.28)","register_no":"15 － 0349","desc":"ろ過池の東北隅に位置する。鉄筋コンクリート造、内径3.6ｍル深さ1.8ｍの円筒形の井戸で、取水ポンプ場からの水を受ける着水井と、ろ過池への送水井の役割を兼ねる。ろ過池とともに浄水場機能の中核を担う施設。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008840"},{"id":"00008841","register_sub_id":"101","register_pk":"162284","name":"三条市水道局大崎浄水場調整池","kana":"さんじょうしすいどうきょくおおさきじょうすいじょうちょうせいち","category":"産業3次","subcategory":"土木構造物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"新潟県","address":"新潟県三条市中新4420-3","lat":37.60881678,"lng":138.99723184,"geo_status":"db","era":"昭和8年","year":1933,"year_source":"db","year_min":1933,"year_max":1933,"year_label":null,"structure":"鉄筋コンクリート造、面積132㎡","structure_material":"鉄筋コンクリート造","registered":"2011.10.28(平成23.10.28)","register_no":"15 － 0350","desc":"送水ポンプ室の南側に位置し、浄水を一時的に貯える施設。鉄筋コンクリート造、東西9.1ｍ南北14.5ｍ深さ3.6ｍで、上部をコンクリート造の屋根と盛土で閉塞し、6基の換気筒を配する。配水池とともに浄水場の最終工程を担う。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008841"},{"id":"00008843","register_sub_id":"101","register_pk":"162286","name":"三条市水道局大崎浄水場配水池","kana":"さんじょうしすいどうきょくおおさきじょうすいじょうはいすいち","category":"産業3次","subcategory":"土木構造物","type_guess":"発電・機械","type_guess_confidence":"low","period":"昭和前","pref":"新潟県","address":"新潟県三条市中新2409-3","lat":37.61037846,"lng":138.99711932,"geo_status":"db","era":"昭和8年","year":1933,"year_source":"db","year_min":1933,"year_max":1933,"year_label":null,"structure":"コンクリート造、面積1344㎡、機械室付","structure_material":"コンクリート造","registered":"2011.10.28(平成23.10.28)","register_no":"15 － 0352","desc":"浄水を貯える施設で敷地北端の丘の上に位置する。コンクリート造、東西２４ｍ南北２８ｍ深さ４．２ｍの二池が東西に並ぶ。上部の盛土上に３６基の換気筒を配し、南面中央に鉄筋コンクリート造平屋建で軽快な意匠の機械室を置く。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008843"},{"id":"00008845","register_sub_id":"101","register_pk":"162288","name":"三条市水道局大崎浄水場門","kana":"さんじょうしすいどうきょくおおさきじょうすいじょうもん","category":"産業3次","subcategory":"その他工作物","type_guess":"塀・門","type_guess_confidence":"high","period":"昭和前","pref":"新潟県","address":"新潟県三条市中新4420-3","lat":37.6085658,"lng":138.99726374,"geo_status":"db","era":"昭和8年","year":1933,"year_source":"db","year_min":1933,"year_max":1933,"year_label":null,"structure":"石造及びコンクリート造、延長13m","structure_material":"石造及びコンクリート造","registered":"2011.10.28(平成23.10.28)","register_no":"15 － 0354","desc":"浄水場敷地の西面中央に開く。花崗岩積でコンクリートを充填した高さ１．８ｍの親柱を４．４ｍ間隔で配し、その左右に袖壁を矩折れに延ばして６本の副柱を配し、モルタル洗出し仕上げとする。堂々とした造りで、昭和初期の浄水場施設の風格を示す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008845"}];
